// Généré par tools/gen_data.py à partir de tools/fiche*.md : ne pas modifier à la main
export const FICHE = {"conception": {"cards": [{"t": "Trois façons de concevoir une structure", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Philosophie</th>\n<th>L'idée</th>\n<th>À retenir</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Safe-life</strong></td>\n<td>La pièce a une <strong>durée de vie fixée</strong> (heures ou cycles). On la retire avant, même si elle a l'air neuve.</td>\n<td>Basée sur des essais de fatigue.</td></tr>\n<tr>\n<td><strong>Fail-safe</strong></td>\n<td><strong>Plusieurs chemins d'effort</strong> : si une pièce casse, les autres reprennent la charge.</td>\n<td>On peut finir le vol et atterrir après une rupture partielle.</td></tr>\n<tr>\n<td><strong>Damage-tolerant</strong></td>\n<td>On <strong>suppose que des fissures existent</strong>. On les trouve aux inspections avant qu'elles deviennent dangereuses.</td>\n<td>Mécanique de la rupture + inspections programmées.</td></tr></tbody></table>\n<p><strong>Pour comprendre</strong> : safe-life = « je jette avant que ça casse », fail-safe = « si ça casse, autre chose tient », damage-tolerant = « je sais que ça fissure, je surveille ».</p>"}, {"t": "Redondance et certification", "kind": "info", "html": "<ul>\n<li><strong>Redondance</strong> : doubler ou tripler ce qui est vital, pour qu'une seule panne ne fasse pas tout tomber. Exemples : 2 génératrices, 3 circuits hydrauliques, 3 canaux de pilote automatique, 2 moteurs.</li>\n<li>La redondance est indispensable aux conceptions fail-safe et damage-tolerant.</li>\n<li><strong>Certification EASA</strong> : tout avion est certifié selon des spécifications (conception, matériaux, fabrication).<ul>\n<li><strong>CS-23</strong> : avions normaux, utilitaires, de voltige et commuter.</li>\n<li><strong>CS-25</strong> : gros avions (avions de transport).</li></ul></li></ul>"}, {"t": "Contraintes et charges", "kind": "info", "html": "<ul>\n<li><strong>Contrainte</strong> (stress) = force interne par unité de surface. <strong>Déformation</strong> (strain) = ce qu'elle produit (allongement, flexion). Elles sont <strong>toujours présentes</strong>, même au parking : le poids comprime le train et fait fléchir les ailes.</li>\n<li>En vol, la portance, la traînée et l'inertie (rafales, facteur de charge) donnent des contraintes <strong>plus fortes</strong> qu'au sol.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Charge</th>\n<th>Exemple</th>\n<th>Ce que fait le pilote</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Statique</strong></td>\n<td>Masse, carburant, au parking ou en croisière</td>\n<td>Gère le carburant et la répartition du chargement</td></tr>\n<tr>\n<td><strong>Dynamique</strong></td>\n<td>Rafale, impact à l'atterrissage, facteur de charge</td>\n<td>Commandes douces, vitesse adaptée en turbulence</td></tr>\n<tr>\n<td><strong>Cyclique</strong></td>\n<td>Cycles de pressurisation, manœuvres répétées</td>\n<td>Peut casser <strong>sous</strong> la résistance maximale : c'est la fatigue</td></tr></tbody></table>\n<p><strong>Zones à surveiller en prévol</strong> : emplanture d'aile, bâti moteur, jonctions du fuselage, attaches des gouvernes. Indices : fissures dans la peinture, bosses, corrosion. Une lampe et un miroir aident.</p>"}, {"t": "Corrosion", "kind": "info", "html": "<ul>\n<li><strong>Corrosion</strong> = oxydation du métal. Elle affaiblit la structure et crée des points de concentration de contraintes.</li>\n<li><strong>À la visite prévol</strong> : poudre blanche ou verdâtre (aluminium), rouille (acier), piqûres, exfoliation (le métal se délite en feuillets).</li>\n<li><strong>Milieux qui l'accélèrent</strong> : eau salée (bord de mer), humidité, pollution, liquides de dégivrage. Parades : laver l'avion, revêtements protecteurs, hangar.</li>\n<li><strong>Fluides corrosifs à bord</strong> : acide de batterie, liquide hydraulique (Skydrol), additifs carburant. Une fuite donne une corrosion locale : chercher les taches.</li></ul>"}, {"t": "Fatigue", "kind": "info", "html": "<ul>\n<li><strong>Fatigue</strong> = une fissure naît puis grandit sous des <strong>charges répétées</strong>, jusqu'à la rupture : <strong>amorçage → propagation → rupture</strong>.</li>\n<li>Elle réduit la durée de vie utile, même si chaque charge est bien sous la résistance maximale.</li>\n<li><strong>Ce qui l'aggrave</strong> :<ul>\n<li>la <strong>corrosion</strong>, qui amorce les fissures ;</li>\n<li>le <strong>nombre de cycles</strong> (décollages, pressurisations) ;</li>\n<li>les manœuvres à <strong>fort facteur de charge</strong> ;</li>\n<li>un <strong>niveau de contrainte</strong> élevé ;</li>\n<li>une <strong>mauvaise maintenance</strong>, qui laisse passer les dommages.</li></ul></li>\n<li>Pré-vol et maintenance protègent contre les deux : corrosion et fatigue.</li></ul>"}, {"t": "Trois types de maintenance", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Principe</th>\n<th>Exemple</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Hard-time</strong> (fixed time)</td>\n<td>Révision ou remplacement à <strong>intervalle fixe</strong>, quel que soit l'état</td>\n<td>TBO d'un moteur</td></tr>\n<tr>\n<td><strong>On-condition</strong></td>\n<td>Inspection périodique ; on intervient <strong>si une mesure sort des limites</strong></td>\n<td>Témoins d'usure des freins, pneus</td></tr>\n<tr>\n<td><strong>Condition monitoring</strong></td>\n<td><strong>Analyse de tendance</strong> des données, <strong>sans limite fixe</strong>, sans démontage</td>\n<td>Analyse d'huile, vibrations, suivi moteur (EHM)</td></tr></tbody></table>\n<p>Les programmes modernes combinent les trois. Hard-time est prudent et prévisible ; on-condition économise les pièces en bon état ; condition monitoring sert aux systèmes complexes.</p>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>On-condition</strong> = une <strong>mesure comparée à une limite</strong>. <strong>Condition monitoring</strong> = une <strong>tendance statistique</strong>, sans limite. Ne les confonds pas.</li>\n<li>Une charge <strong>cyclique</strong> peut casser une pièce <strong>sous</strong> sa résistance maximale : c'est la définition de la fatigue.</li>\n<li><strong>Fail-safe</strong> n'est pas « ça ne casse jamais » : c'est « si ça casse, autre chose tient ».</li>\n<li><strong>CS-25</strong> = gros avions, <strong>CS-23</strong> = petits. Pas l'inverse.</li></ul>"}], "oral": ["Définis et compare les philosophies safe-life, fail-safe et damage-tolerant.", "Pourquoi la redondance est-elle indispensable sur un avion de transport ? Donne trois exemples.", "Cite les trois types de charges, avec un exemple et l'action du pilote pour chacune.", "Qu'est-ce que la fatigue ? Donne ses trois étapes et cinq facteurs qui l'aggravent.", "Comment reconnaît-on la corrosion en visite prévol ? Quels milieux et quels fluides l'accélèrent ?", "Compare la maintenance hard-time, on-condition et condition monitoring, avec un exemple chacune."]}, "structure": {"cards": [{"t": "Les assemblages", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Méthode</th>\n<th>Où</th>\n<th>Point faible ou contrôle</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Rivetage</strong> (permanent)</td>\n<td>Peau sur cadre</td>\n<td>Fissures autour des trous ; forte résistance au cisaillement</td></tr>\n<tr>\n<td><strong>Soudage</strong></td>\n<td>Bâtis métalliques, bâti moteur</td>\n<td>Fissures ; rare en structure primaire</td></tr>\n<tr>\n<td><strong>Boulonnage</strong> (démontable)</td>\n<td>Attaches moteur, timonerie</td>\n<td>Couple de serrage, repères de couple, fils à freiner</td></tr>\n<tr>\n<td><strong>Goupillage</strong></td>\n<td>Charnières, pivots</td>\n<td>Reprend le cisaillement ; goupille fendue de sécurité</td></tr>\n<tr>\n<td><strong>Collage</strong></td>\n<td>Composites, nid d'abeille</td>\n<td>Répartit bien les efforts, léger ; mais <strong>défauts cachés</strong></td></tr>\n<tr>\n<td><strong>Vissage</strong></td>\n<td>Trappes, carénages</td>\n<td>Se desserre aux vibrations, filetage arraché</td></tr></tbody></table>\n<p><strong>En prévol</strong> : fixation manquante ou desserrée, jeu (on secoue), corrosion, fissures, traces de fuite, fil à freiner ou goupille absents.</p>"}, {"t": "Les matériaux composites", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> : une <strong>matrice</strong> (résine) + un <strong>renfort</strong> (fibres). La résistance est <strong>anisotrope</strong> : on oriente les fibres dans le sens des efforts.</li>\n<li><strong>Fibres</strong> : carbone (résistance et rigidité), verre (pas cher, isolant), Kevlar ou aramide (résistance aux chocs). <strong>Résines</strong> : époxy, polyester.</li>\n<li><strong>Avantages sur les alliages</strong> : meilleur rapport résistance/masse, résistance orientable, rigidité comparable, excellente tenue à la <strong>fatigue</strong> et à la <strong>corrosion</strong>.</li>\n<li><strong>Inconvénients</strong> : mauvaise <strong>conductivité</strong> électrique (foudre : on ajoute un grillage métallique), <strong>coût</strong>, <strong>dégâts internes invisibles</strong> (délaminage : il faut un contrôle non destructif, par ultrasons).</li>\n<li>On choisit selon la charge, la masse, l'environnement, le coût : alliages d'aluminium (fuselage), titane (zones chaudes), acier (train), composites (ailes).</li></ul>"}, {"t": "Aile haute ou basse, empennage classique ou en T", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Configuration</th>\n<th>Avantages</th>\n<th>Inconvénients</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Aile haute</strong></td>\n<td>Garde au sol de l'hélice, stabilité (effet dièdre), fuselage dégagé</td>\n<td>CG plus haut, structure plus complexe</td></tr>\n<tr>\n<td><strong>Aile basse</strong></td>\n<td>CG bas, accès facile, train simple, effet de sol</td>\n<td>Risque de toucher le sol avec l'hélice, traînée d'interférence</td></tr>\n<tr>\n<td><strong>Empennage bas ou médian</strong></td>\n<td>Structure simple ; médian = hors du souffle moteur</td>\n<td>—</td></tr>\n<tr>\n<td><strong>Empennage en T</strong></td>\n<td>Aéro propre, meilleur contrôle en tangage, effet de plaque sur la dérive</td>\n<td><strong>Super-décrochage</strong> (deep stall), dérive plus chargée, maintenance difficile</td></tr></tbody></table>"}, {"t": "Les pièces de l'aile", "kind": "info", "html": "<ul>\n<li><strong>Longeron</strong> : la poutre principale, qui reprend <strong>flexion et cisaillement</strong>. L'<strong>âme</strong> (plaque verticale) prend le cisaillement ; les <strong>semelles</strong> (haut et bas) prennent traction et compression.</li>\n<li><strong>Nervure</strong> : garde la <strong>forme du profil</strong>, transmet les efforts de la peau au longeron, cloisonne les réservoirs.</li>\n<li><strong>Lisse</strong> (stringer) : raidisseur dans le sens de l'envergure, qui empêche la peau de <strong>flamber</strong>.</li>\n<li><strong>Revêtement</strong> : prend cisaillement et torsion, et donne la surface aérodynamique. Avec les lisses : peau travaillante.</li>\n<li><strong>Caisson de torsion</strong> : la boîte fermée longerons + nervures + peau, qui <strong>résiste à la torsion</strong> et contient souvent le <strong>carburant</strong>.</li></ul>"}, {"t": "Le flottement (flutter)", "kind": "info", "html": "<ul>\n<li><strong>C'est quoi</strong> : un couplage <strong>aéroélastique flexion + torsion</strong>. Quand la fréquence propre de l'aile ou d'une gouverne entre en <strong>résonance</strong> avec les forces aérodynamiques, l'oscillation s'amplifie. Il dépend de la <strong>vitesse</strong> et peut détruire l'aile en quelques secondes.</li>\n<li><strong>Les parades</strong> :<ul>\n<li>des <strong>masses</strong> placées le long de la corde et de l'envergure (moteurs, carburant, <strong>masses d'équilibrage des gouvernes</strong>), pour décaler le centre de gravité et découpler les modes ;</li>\n<li>une bonne <strong>rigidité en torsion</strong>, pour monter la fréquence propre ; un peu de souplesse en flexion absorbe l'énergie ;</li>\n<li>l'<strong>équilibrage du carburant</strong>, pour éviter une masse dissymétrique.</li></ul></li>\n<li><strong>Charges dissymétriques</strong> : panne moteur sur bimoteur, glissade → gros efforts sur la dérive. Le pilote peut surcharger la structure avec trop de palonnier ou trop de vitesse.</li></ul>"}, {"t": "Le fuselage", "kind": "info", "html": "<ul>\n<li><strong>Monocoque</strong> : la peau porte tout. <strong>Semi-monocoque</strong> (le plus courant) : peau + structure interne.</li>\n<li><strong>Pièces</strong> : cadres (forme), cloisons (compartiments, étanchéité), lisses et longerons (rigidité dans la longueur), doublures (renforts), plancher, <strong>cloison pare-feu</strong> (sépare le moteur).</li>\n<li><strong>Pressurisation</strong> : traction <strong>circonférentielle</strong> dans la peau (comme un ballon) + effort longitudinal sur les cloisons → <strong>fatigue cyclique</strong> à chaque vol.</li>\n<li><strong>Sections</strong> : circulaire = la meilleure en pression ; double bulle = plus de plancher ; ovale ; rectangulaire = cargo, angles très contraints, non pressurisée.</li>\n<li><strong>Portes « plug »</strong> : plus grandes que leur ouverture, la pression les plaque sur leur cadre.</li>\n<li><strong>Atterrissage dur</strong> sur la roue avant : forte flexion du fuselage. <strong>Tail strike</strong> : cloison arrière abîmée, fuite de pressurisation.</li></ul>"}, {"t": "Pare-brise et plancher", "kind": "info", "html": "<ul>\n<li><strong>Pare-brise</strong> : plusieurs couches (structurale, chauffante, antigivre). Le chauffage évite les fissures et le givre. Vue directe, claire et sans distorsion exigée (CS 25.773).</li>\n<li><strong>Ventilation du plancher</strong> : la soute est pressurisée comme la cabine.</li>\n<li><strong>Panneaux blow-out</strong> : en décompression, ils s'ouvrent tout seuls pour <strong>égaliser la pression</strong> entre cabine et soute. Sans eux, le plancher pourrait s'effondrer (et couper les câbles de commandes qui passent dessous).</li></ul>"}, {"t": "Les masses limites", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Masse</th>\n<th>Définition</th>\n<th>Pourquoi cette limite</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>MRM</strong> (rampe)</td>\n<td>Max pour rouler, carburant de mise en route compris</td>\n<td>La plus élevée au sol</td></tr>\n<tr>\n<td><strong>MTOM</strong> (décollage)</td>\n<td>Max au lâcher des freins</td>\n<td>Structure + performances</td></tr>\n<tr>\n<td><strong>MZFM</strong> (sans carburant)</td>\n<td>Max sans carburant utilisable</td>\n<td>Le carburant dans l'aile <strong>soulage la flexion</strong> : sans lui, l'emplanture est la plus chargée</td></tr>\n<tr>\n<td><strong>MLM</strong> (atterrissage)</td>\n<td>Max à l'impact</td>\n<td>Limite d'absorption d'énergie, plus basse que la MTOM</td></tr></tbody></table>\n<p><strong>Pour comprendre la MZFM</strong> : la portance tire l'aile vers le haut, le carburant dans l'aile pèse vers le bas au même endroit. Plus il y a de charge dans le fuselage et moins il y a de carburant dans les ailes, plus l'emplanture fléchit.</p>\n<p><strong>Ordre</strong> : MRM ≥ MTOM ≥ MLM. Exemple célèbre de fatigue + corrosion : Aloha Airlines 243 (1988), une partie du toit arrachée en vol.</p>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>La <strong>nervure</strong> donne la forme ; c'est la <strong>lisse</strong> qui empêche le flambage de la peau.</li>\n<li><strong>Âme</strong> du longeron = cisaillement ; <strong>semelles</strong> = traction/compression.</li>\n<li>La MZFM protège <strong>l'emplanture de l'aile</strong> (flexion), pas le train.</li>\n<li>Les composites résistent <strong>bien</strong> à la fatigue et à la corrosion ; leur problème, ce sont les <strong>dégâts cachés</strong>, la <strong>foudre</strong> et le <strong>coût</strong>.</li>\n<li>Empennage en T = risque de <strong>super-décrochage</strong> (deep stall).</li></ul>"}], "oral": ["Cite les méthodes d'assemblage et le point faible ou le contrôle de chacune.", "Qu'est-ce qu'un matériau composite ? Donne ses avantages et ses inconvénients face aux alliages.", "Décris le rôle du longeron, de la nervure, de la lisse, du revêtement et du caisson de torsion.", "Explique le flottement et les trois familles de contre-mesures.", "Pourquoi la section circulaire est-elle la meilleure pour la pressurisation ? À quoi servent les panneaux blow-out ?", "Définis MRM, MTOM, MZFM et MLM. Pourquoi existe-t-il une masse maximale sans carburant ?"]}, "feu": {"cards": [{"t": "Détecteur de fumée optique", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> (effet Tyndall) : une LED infrarouge et une photodiode sont placées <strong>en angle</strong>. En air propre, la lumière passe tout droit et <strong>n'atteint pas</strong> le récepteur. Quand la fumée entre, les particules <strong>diffusent</strong> la lumière vers le récepteur → alarme.</li>\n<li><strong>Bon pour</strong> : les grosses particules visibles, les <strong>feux couvants</strong> (câbles qui chauffent, isolants, batteries lithium). Stable dans les zones très ventilées (soutes, circuits de clim).</li>\n<li><strong>Limites</strong> : plus lent sur un feu vif ; sensible à l'encrassement (poussière, lentille sale) → nettoyage et étalonnage.</li>\n<li>C'est le <strong>standard dans les soutes</strong>.</li></ul>"}, {"t": "Détecteur de fumée ionique", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> : un peu d'<strong>américium 241</strong> ionise l'air entre deux électrodes, un petit courant passe. La fumée <strong>capte les ions</strong>, ils bougent moins, <strong>le courant chute</strong> → alarme.</li>\n<li><strong>Bon pour</strong> : les petites particules invisibles, les feux <strong>rapides et chauds</strong> (carburant, arcs électriques), les baies avioniques. Très sensible dès le début du feu.</li>\n<li><strong>Limite</strong> : <strong>fausses alarmes</strong> avec la poussière, l'humidité, les vapeurs d'huile ou de liquide hydraulique.</li>\n<li>Les avions modernes utilisent des capteurs <strong>doubles</strong> (optique + ionique) ou <strong>multicritères</strong> (fumée + chaleur + CO) : moins de fausses alarmes, et les deux types de feu sont couverts.</li>\n<li><strong>Alarmes</strong> : voyant SMOKE, message ECAM/EICAS avec le lieu (FWD CARGO SMOKE, LAV SMOKE), Master Caution ou Warning. <strong>Test</strong> avant chaque vol : bouton SMOKE TEST.</li></ul>"}, {"t": "Extinction incendie", "kind": "info", "html": "<ul>\n<li><strong>Agent</strong> : <strong>Halon 1301</strong> (ou HFC-125) sous pression. Il <strong>casse la réaction chimique</strong> de la combustion. Avantage : très rapide, abîme peu les équipements.</li>\n<li><strong>Composants</strong> : bouteilles, vannes à <strong>cartouche pyrotechnique</strong> (squib) ou électriques, tuyauterie, buses ou tubes percés, manocontacts de charge, boutons ENG 1 FIRE, ENG 2 FIRE, CARGO FIRE.</li>\n<li><strong>Règle</strong> (CS 25.1195(c)) : <strong>2 décharges par moteur</strong> (deux bouteilles, ou une double), pour un <strong>second tir</strong> si le feu persiste ou reprend.</li>\n<li><strong>Soute</strong> : décharge forte, puis <strong>débit dosé de longue durée</strong> pour garder peu d'oxygène longtemps.</li></ul>"}, {"t": "Détection incendie", "kind": "info", "html": "<ul>\n<li>Les détecteurs mesurent la <strong>chaleur</strong>, pas la flamme.</li>\n<li><strong>Principes</strong> : un matériau dont la <strong>résistance ou la capacité</strong> change beaucoup avec la chaleur ; ou un <strong>gaz</strong> qui se dilate et pousse un manocontact.</li>\n<li><strong>Technologies</strong> : <strong>bilame</strong> (détecteur ponctuel, simple) ; <strong>boucle continue</strong> le long du moteur (type résistance ou type pression) ; <strong>boucle à gaz</strong> (rapide et fiable).</li>\n<li><strong>Double boucle A + B</strong> : redondance + <strong>moins de fausses alarmes</strong>, car il faut souvent que les <strong>deux</strong> boucles voient le feu (logique ET). Une boucle en panne = simple caution ; les deux détectent = alarme feu.</li>\n<li><strong>Le détecteur idéal</strong> : aucune fausse alarme, alerte rapide et localisée, indique la fin du feu et sa reprise, alerte continue pendant le feu, testable depuis le cockpit, robuste (huile, eau, vibrations, températures).</li>\n<li><strong>Alarme</strong> : voyant FIRE rouge, message ECAM (ENG 1 FIRE), Master Warning, alarme sonore. <strong>Test</strong> : bouton FIRE TEST (boucles + circuits de squibs).</li></ul>"}, {"t": "Protection contre la pluie", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Moyen</th>\n<th>Principe</th>\n<th>Limite</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Essuie-glaces</strong></td>\n<td>Bras électriques ou hydrauliques, 2 vitesses, position parking</td>\n<td>Peu efficaces en forte pluie et à grande vitesse : les balais décollent</td></tr>\n<tr>\n<td><strong>Liquide anti-pluie</strong></td>\n<td>Jet de liquide siliconé : l'eau perle et s'envole</td>\n<td>Consommable, à refaire ; vue déformée si on en met trop. <strong>Très efficace à grande vitesse</strong></td></tr>\n<tr>\n<td><strong>Revêtement hydrophobe</strong></td>\n<td>Couche transparente permanente sur la vitre</td>\n<td>Passif, sans action du pilote, mais s'use : à refaire en maintenance</td></tr></tbody></table>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>Optique</strong> = la lumière diffusée <strong>arrive</strong> au récepteur. <strong>Ionique</strong> = le courant <strong>diminue</strong>.</li>\n<li>L'optique est le <strong>standard en soute</strong> (feux couvants, batteries lithium) ; l'ionique donne des <strong>fausses alarmes</strong>.</li>\n<li>Les détecteurs incendie sentent la <strong>chaleur</strong>, pas les flammes.</li>\n<li><strong>2 décharges</strong> par moteur, pas 1.</li>\n<li>Double boucle en logique <strong>ET</strong> : moins de fausses alarmes. Une seule boucle en panne ne déclenche qu'une caution.</li></ul>"}], "oral": ["Explique le principe du détecteur de fumée optique et du détecteur ionique. Lequel est préféré en soute, et pourquoi ?", "Décris un système d'extinction moteur : agent, composants, nombre de décharges exigé.", "Pourquoi utilise-t-on deux boucles de détection ? Quelle est la logique d'alarme ?", "Cite les qualités d'un système de détection incendie idéal.", "Compare les trois moyens de protection contre la pluie."]}, "hydraulique": {"cards": [{"t": "Les lois de base", "kind": "info", "html": "<ul>\n<li><strong>Hydromécanique</strong> : l'étude des liquides au repos (hydrostatique) ou en mouvement (hydrodynamique). En avion, on utilise un liquide <strong>incompressible</strong> pour transmettre une puissance (freins, train, commandes).</li>\n<li><strong>Pression hydrostatique</strong> : P = ρ × g × h. Elle augmente avec la profondeur et <strong>ne dépend pas de la forme du récipient</strong>.</li>\n<li><strong>Loi de Pascal</strong> : une pression appliquée à un liquide enfermé se transmet <strong>intégralement et dans toutes les directions</strong>. C'est ce qui permet d'agir à distance.</li>\n<li><strong>P = F / A</strong>, donc <strong>F = P × A</strong> et A = F / P. Unité : le pascal (Pa = N/m²).</li></ul>"}, {"t": "Multiplier une force", "kind": "info", "html": "<ul>\n<li>Une <strong>petite force</strong> sur un <strong>petit piston</strong> crée une pression. Cette même pression sur un <strong>grand piston</strong> donne une <strong>grande force</strong>.</li>\n<li><strong>Contrepartie</strong> : le volume de liquide est conservé. Le petit piston fait une longue course, le grand une <strong>petite course</strong>. Travail entrant = travail sortant (hors pertes) : on ne crée pas d'énergie.</li></ul>\n<p><strong>Exemple</strong> : 100 N sur un piston de 1 cm² créent une pression de 100 N/cm². Sur un piston de 10 cm², cette même pression donne <strong>1 000 N</strong>. Mais si le petit piston descend de 10 cm, le grand ne monte que de <strong>1 cm</strong>.</p>"}, {"t": "Le liquide hydraulique", "kind": "info", "html": "<ul>\n<li><strong>Qualités recherchées</strong> : stabilité thermique (pas de vernis ni de boues), non corrosif, <strong>point éclair élevé (≈ 200 °C)</strong>, faible volatilité, <strong>viscosité stable</strong> avec la température (pour l'étanchéité et le rendement des pompes).</li>\n<li><strong>Types</strong> : <strong>synthétique</strong> (ester phosphate, <strong>Skydrol</strong>) ou <strong>minéral</strong> (dérivé du pétrole). <strong>Jamais de mélange</strong> : mousse, gel.</li>\n<li>Irritant pour la peau et les yeux : gants et lunettes. Incompressible à 3 000 psi et plus.</li></ul>"}, {"t": "Principes d'un circuit", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> : pompe → conduites → vérins → retour au réservoir.</li>\n<li><strong>Pression constante</strong> (toujours pressurisé : commandes de vol, gros avions) <strong>ou à la demande</strong> (pressurisé seulement si besoin : train d'un petit avion, portes cargo ; économise la puissance).</li>\n<li><strong>Actif</strong> (une pompe maintient la pression) <strong>ou passif</strong> (énergie stockée : ressort, gaz). Actif en principal, passif en secours.</li>\n<li><strong>Usages</strong> : commandes de vol, train, freins, inverseurs de poussée.</li>\n<li><strong>Pressions</strong> : basse ≤ 2 000 psi ; haute <strong>3 000 psi</strong> en général, 4 000 à 5 000 psi sur A350. La haute pression donne des vérins et des tuyaux plus petits, plus légers et plus réactifs, mais plus de contraintes, de fuites et des joints complexes.</li></ul>"}, {"t": "Les sources de pression", "kind": "info", "html": "<ul>\n<li><strong>Pompes</strong> : à <strong>plateau inclinable</strong> (cylindrée variable, garde une <strong>pression constante</strong>) ; à <strong>engrenages</strong> (cylindrée fixe, débit lié au régime).</li>\n<li><strong>Manuelle</strong> (secours, lente et peu puissante) ; <strong>moteur ou boîtier d'accessoires</strong> (principale ; perdue si le moteur s'arrête) ; <strong>électrique</strong> (secours, petits circuits).</li>\n<li><strong>Pneumatique</strong> (air prélevé) ou <strong>RAT</strong> (éolienne de secours : <strong>dépend de la vitesse</strong>).</li>\n<li><strong>PTU</strong> (unité de transfert) : un circuit en entraîne un autre. Elle <strong>transfère de la puissance, pas du liquide</strong> : inutile si le circuit fuit.</li>\n<li><strong>APU</strong> ou groupe de parc. <strong>Pompe de demande</strong> : pompe d'appoint pour les gros débits (rentrée du train, volets).</li>\n<li><strong>Redondance</strong> : plusieurs sources, plusieurs circuits, plusieurs vérins par gouverne.</li></ul>"}, {"t": "Les composants", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Composant</th>\n<th>Rôle</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Réservoir</strong></td>\n<td>Stocke le liquide (pressurisé ou non)</td></tr>\n<tr>\n<td><strong>Accumulateur</strong></td>\n<td>Stocke de la <strong>pression</strong>, amortit les à-coups, sert de secours</td></tr>\n<tr>\n<td><strong>Filtre</strong></td>\n<td>Retient les particules ; <strong>by-pass</strong> s'il est colmaté</td></tr>\n<tr>\n<td><strong>Clapet anti-retour</strong></td>\n<td>Passage dans <strong>un seul sens</strong>, comme une diode</td></tr>\n<tr>\n<td><strong>Soupape de sûreté</strong> (relief)</td>\n<td>Renvoie au réservoir en cas de surpression</td></tr>\n<tr>\n<td><strong>Restricteur</strong></td>\n<td>Limite le débit, donc la <strong>vitesse</strong> du vérin</td></tr>\n<tr>\n<td><strong>Servovalve (EHSV)</strong></td>\n<td>Commande électrique précise de position, vitesse, effort</td></tr>\n<tr>\n<td><strong>Vanne by-pass</strong></td>\n<td>Chemin de contournement (isolement pour la maintenance)</td></tr>\n<tr>\n<td><strong>Valve navette</strong> (shuttle)</td>\n<td>Reçoit le liquide de l'<strong>une de deux sources</strong></td></tr>\n<tr>\n<td><strong>Vanne coupe-feu</strong></td>\n<td>Fusible thermique : se ferme à une température donnée</td></tr>\n<tr>\n<td><strong>Vanne de priorité</strong></td>\n<td>Sert d'abord l'utilisateur prioritaire, le reste ensuite</td></tr>\n<tr>\n<td><strong>Fusible hydraulique</strong></td>\n<td>Coupe une branche qui fuit au-delà d'un débit seuil, protège le reste</td></tr>\n<tr>\n<td><strong>Vérin</strong></td>\n<td>Simple effet (retour par ressort) ou double effet</td></tr>\n<tr>\n<td><strong>Moteur hydraulique</strong></td>\n<td>Transforme la pression en rotation (parfois réversible)</td></tr></tbody></table>\n<p>Conduites de pression en acier ou titane ; conduites de retour basse pression, plus grosses. <strong>Case drain</strong> : récupère les fuites internes d'une pompe ou d'un moteur.</p>"}, {"t": "Les pannes", "kind": "info", "html": "<ul>\n<li><strong>Fuite ou niveau bas</strong> : lente ou rapide ; surchauffe, perte des gros consommateurs, <strong>risque de feu</strong>. Surveillée par la <strong>jauge de niveau</strong> du réservoir.</li>\n<li><strong>Pression basse</strong> : mouvements lents, séquence incomplète (le vérin manque de force). Surveillée par le <strong>manomètre</strong>.</li>\n<li><strong>Température haute</strong> : liquide dégradé, composants abîmés, fuites, feu. Surveillée par le <strong>thermomètre</strong>.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>L'<strong>accumulateur</strong> stocke de la <strong>pression</strong> ; c'est le <strong>réservoir</strong> qui stocke le <strong>liquide</strong>.</li>\n<li>La <strong>PTU</strong> ne rajoute pas de liquide : elle ne sauve pas un circuit qui fuit.</li>\n<li>La <strong>RAT</strong> dépend de la vitesse.</li>\n<li>Pompe à <strong>plateau</strong> = pression constante ; pompe à <strong>engrenages</strong> = débit fixe lié au régime.</li>\n<li>Le grand piston gagne en <strong>force</strong> mais perd en <strong>course</strong> : le travail est conservé.</li></ul>"}], "oral": ["Énonce la loi de Pascal et explique comment un circuit hydraulique multiplie une force.", "Quelles qualités doit avoir un liquide hydraulique ? Pourquoi ne mélange-t-on jamais deux types ?", "Compare un circuit à pression constante et un circuit à la demande, un circuit actif et un circuit passif.", "Cite les sources de pression hydraulique et la limite de chacune (RAT, PTU, pompe manuelle).", "Donne le rôle de l'accumulateur, du clapet anti-retour, de la soupape de sûreté, de la valve navette et du fusible hydraulique.", "Quelles sont les pannes typiques et comment les surveille-t-on ?"]}, "train": {"cards": [{"t": "Tricycle ou train classique", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Train</th>\n<th>Avantages</th>\n<th>Inconvénients</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Tricycle</strong> (roue avant)</td>\n<td>Fuselage horizontal (chargement facile), bon freinage et contrôle au sol, stable à l'atterrissage, bonne visibilité, moins de traînée au début du roulage</td>\n<td>Garde au sol de l'hélice réduite, plus de traînée en train fixe</td></tr>\n<tr>\n<td><strong>Classique</strong> (roulette de queue)</td>\n<td>Roulette légère (loin du CG, peu chargée), bon sur terrain sommaire, bonne garde d'hélice</td>\n<td><strong>Capotage</strong>, mauvaise visibilité vers l'avant au roulage, <strong>cheval de bois</strong></td></tr></tbody></table>"}, {"t": "Les pièces du train", "kind": "info", "html": "<ul>\n<li><strong>Amortisseur oléopneumatique</strong> : l'<strong>huile</strong> passe par un orifice et un pointeau dosé (elle amortit), l'<strong>azote</strong> se comprime (il fait ressort). L'énergie verticale de l'atterrissage devient de la <strong>chaleur</strong>.</li>\n<li><strong>Essieu, bogie</strong> : porte une ou plusieurs roues (A380 : bogies à 4 roues).</li>\n<li><strong>Contrefiche</strong> (avant-arrière), <strong>contrefiche latérale</strong> (qui se replie), <strong>compas</strong> (torsion links) : garde la roue alignée et empêche la tige de tourner.</li>\n<li><strong>Verrou bas</strong> : la contrefiche passe <strong>au-delà du point mort</strong> (over-center) en fin de course du vérin. <strong>Verrou haut</strong> : crochet à ressort et vérin.</li>\n<li><strong>Trappes</strong> : liées au train ou autonomes, à commande mécanique, hydraulique ou pneumatique.</li></ul>"}, {"t": "Séquences et voyants", "kind": "info", "html": "<ul>\n<li><strong>Rentrée</strong> : levier UP → trappes ouvertes → déverrouillage bas → le vérin rentre le train → trappes fermées.</li>\n<li><strong>Sortie</strong> : levier DOWN → trappes ouvertes → déverrouillage haut → le train sort (chute ou vérin) → verrou bas → trappes fermées.</li>\n<li><strong>Voyants</strong> : <strong>3 verts</strong> = sorti et verrouillé ; <strong>rouge</strong> = en transit ou non verrouillé ; <strong>aucun voyant</strong> = désaccord ou ampoule grillée.</li>\n<li><strong>Klaxon</strong> si le train est rentré avec la puissance réduite (ou les volets sortis).</li>\n<li><strong>Au sol, contre une rentrée accidentelle</strong> : goupilles à flamme rouge, <strong>contacteur train comprimé</strong> (WOW, squat switch) qui bloque le levier, verrou mécanique dans le vérin.</li>\n<li><strong>VLO</strong> = vitesse max pour manœuvrer le train ; <strong>VLE</strong> = vitesse max train sorti. VLO ≤ VLE.</li></ul>"}, {"t": "Sortie de secours", "kind": "info", "html": "<ol>\n<li><strong>Déverrouiller</strong> les verrous hauts (câble ou levier).</li>\n<li><strong>Faire sortir</strong> le train : <strong>par gravité</strong> (le plus courant), aidée par un ressort, ou par une bouteille d'<strong>azote</strong>, ou par une <strong>manivelle</strong> ou une pompe à main.</li>\n<li>Le <strong>verrou bas</strong> s'enclenche tout seul.</li></ol>\n<p>Certains avions combinent deux méthodes.</p>"}, {"t": "Direction au sol", "kind": "info", "html": "<ul>\n<li><strong>Freinage différentiel + roulette folle</strong> (avions légers) : simple et léger, mais lent et use freins et pneus.</li>\n<li><strong>Tiller</strong> (petit volant) : <strong>grand débattement (±70 à 85°)</strong>, pour les virages serrés à basse vitesse.</li>\n<li><strong>Palonnier</strong> : <strong>petit débattement (±6 à 15°)</strong>, pour le roulage rapide et le décollage ; au-delà de ~40 à 60 kt, la gouverne de direction prend le relais.</li>\n<li><strong>Centrage</strong> de la roue avant <strong>obligatoire avant la rentrée</strong> (came, vérin de centrage, ressorts), sinon elle n'entre pas dans sa case.</li>\n<li><strong>Shimmy</strong> : oscillation violente et rapide de la roue (flexion du pneu + inertie + jeu). Usure, fatigue, perte de contrôle. Parade : <strong>amortisseur de shimmy</strong> + compas.</li>\n<li><strong>Body steering</strong> (A380, 747-8) : les bogies arrière s'orientent. Moins d'usure des pneus, virage plus serré (demi-tour sur 50 à 55 m) ; coupé au-dessus de ~20 kt.</li></ul>"}, {"t": "Roues et pneus", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Pneu</th>\n<th>Avantages</th>\n<th>Inconvénients</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Tubeless</strong> (standard)</td>\n<td>Plus léger, dégonfle lentement en cas de crevaison, refroidit mieux</td>\n<td>Exige une jante parfaitement étanche</td></tr>\n<tr>\n<td><strong>Diagonal</strong> (nappes croisées à ~45°)</td>\n<td>Robuste, flancs solides, résiste aux coupures</td>\n<td>Lourd, chauffe, raide</td></tr>\n<tr>\n<td><strong>Radial</strong> (nappes à 90° + ceintures)</td>\n<td>Léger, chauffe moins, meilleure adhérence et usure, vitesse plus haute</td>\n<td>Flancs vulnérables aux coupures</td></tr></tbody></table>\n<ul>\n<li><strong>Ply rating</strong> = indice de résistance (charge), <strong>pas</strong> le nombre réel de nappes. <strong>Rechapage</strong> : nouvelle bande sur une carcasse usée.</li>\n<li><strong>Creep</strong> : le pneu tourne lentement sur la jante → on vérifie l'alignement des repères peints.</li>\n<li><strong>Bouchons fusibles</strong> dans la jante : ils fondent vers <strong>180 à 300 °C</strong> et dégonflent le pneu <strong>avant qu'il explose</strong> (après un décollage interrompu ou un freinage fort).</li>\n<li><strong>Vitesse limite du pneu</strong> : la force centrifuge croît avec V². Radial ≈ 220 à 250 kt. On peut la dépasser au décollage <strong>vent arrière</strong> (vitesse sol plus grande).</li>\n<li><strong>Prévol</strong> : coupures et hernies (corps étrangers, atterrissage dur), <strong>méplats</strong> (roue bloquée qui a ripé), gonflage, repères de creep, usure.</li></ul>"}, {"t": "Les freins", "kind": "info", "html": "<ul>\n<li><strong>Freins à disques</strong> : disques (rotors) entraînés par la roue, plaquettes fixes qui serrent. L'énergie cinétique devient de la <strong>chaleur</strong>. Plusieurs disques empilés.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Matériau</th>\n<th>Masse</th>\n<th>Température max</th>\n<th>Frottement</th>\n<th>Usure et coût</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Acier</strong></td>\n<td>Lourd</td>\n<td>~800 à 1 000 °C</td>\n<td>Élevé, constant</td>\n<td>Correcte ; moins cher, simple</td></tr>\n<tr>\n<td><strong>Carbone</strong></td>\n<td>40 à 50 % plus léger</td>\n<td>&gt; 1 600 °C</td>\n<td>Faible à froid, <strong>augmente avec la température</strong></td>\n<td>2 à 4 fois meilleure ; cher, mauvais au roulage</td></tr></tbody></table>\n<ul>\n<li><strong>Énergie limite</strong> des freins : au-delà, fading, feu, fusion des bouchons → c'est une limite du décollage interrompu.</li>\n<li><strong>Commande</strong> : hydraulique non assistée (pédale → maître-cylindre, petits avions) ; assistée (servo) ; électrique (brake-by-wire).</li>\n<li><strong>Freinage des roues pendant la rentrée</strong> : évite les vibrations et les projections dans la case.</li>\n<li><strong>Accumulateur de freins</strong> : plusieurs freinages sans pompe. <strong>Frein de parc</strong> : garde la pression.</li>\n<li><strong>Témoins d'usure</strong> : quand la tige ne dépasse plus, on change. <strong>Température</strong> surveillée : un <strong>feu de freins chauds peut se déclarer longtemps après</strong> l'arrêt.</li></ul>"}, {"t": "Anti-skid et autobrake", "kind": "info", "html": "<ul>\n<li><strong>Anti-skid</strong> : empêche le blocage des roues en relâchant la pression. Il compare chaque roue à une vitesse de référence (inertielle ou roue la plus rapide) et vise <strong>10 à 15 % de glissement</strong>, là où l'adhérence est <strong>maximale</strong>.</li>\n<li><strong>Protections</strong> : <strong>roue bloquée</strong> (une roue presque arrêtée alors que les autres tournent → on relâche) ; <strong>toucher des roues</strong> (pas de freinage avant WOW + mise en rotation) ; <strong>aquaplaning</strong> (décélération trop faible malgré la pression → on relâche pour que la roue reprenne sa rotation).</li>\n<li><strong>Vitesse d'aquaplaning (kt) = 9 × √P</strong>, P = pression du pneu en psi. Exemple : 100 psi → 90 kt ; 200 psi → ≈ 127 kt.</li>\n<li><strong>Autobrake</strong> : freine seul après le toucher (ou en RTO) à <strong>décélération constante</strong>. <strong>Impossible sans anti-skid</strong>. Modes : OFF, ARMED, actif, désactivé par action sur les pédales.</li>\n<li><strong>A320neo</strong> : <strong>MAX</strong> = décollage seulement (RTO, pression max) ; <strong>MED</strong> = 3 m/s² (piste courte ou mouillée) ; <strong>LO</strong> = 2 m/s². Freinage 2 s après la sortie des spoilers. Voyant DECEL = 80 % de la décélération visée ; il peut rester éteint sur piste glissante sans que l'autobrake soit en panne.</li>\n<li>Les inverseurs réduisent le travail des freins ; une piste glissante réduit la décélération obtenue.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>3 verts</strong> = sorti verrouillé ; <strong>rouge</strong> = transit ; <strong>rien</strong> = désaccord ou ampoule.</li>\n<li>Palonnier = <strong>petit</strong> débattement ; tiller = <strong>grand</strong> débattement.</li>\n<li>Le carbone freine <strong>mieux à chaud</strong> et mal au roulage.</li>\n<li>Ply rating ≠ nombre de plis.</li>\n<li>Le voyant DECEL éteint sur piste glissante ne veut pas dire que l'autobrake est en panne.</li>\n<li>La vitesse pneu peut être dépassée <strong>vent arrière</strong>.</li></ul>"}], "oral": ["Compare le train tricycle et le train classique.", "Décris le fonctionnement d'un amortisseur oléopneumatique et le rôle du compas.", "Donne les séquences de rentrée et de sortie du train, les voyants et les protections au sol.", "Comment fait-on une sortie de secours du train ?", "Qu'est-ce que le shimmy et comment l'évite-t-on ? Pourquoi centre-t-on la roue avant ?", "Compare freins acier et carbone. À quoi servent les bouchons fusibles ?", "Explique le principe de l'anti-skid et ses trois protections. Calcule la vitesse d'aquaplaning d'un pneu à 144 psi."]}, "commandes": {"cards": [{"t": "Primaires et secondaires", "kind": "info", "html": "<ul>\n<li><strong>Commandes primaires</strong> : tangage, roulis, lacet. Elles sont indispensables au vol.<ul>\n<li><strong>Profondeur</strong> : tangage.</li>\n<li><strong>Ailerons</strong>, <strong>spoilers de roulis</strong>, <strong>flaperons</strong> : roulis.</li>\n<li><strong>Direction</strong> : lacet, et contre la poussée dissymétrique.</li></ul></li>\n<li><strong>Commandes secondaires</strong> : elles modifient portance, traînée ou trim, sans être indispensables au contrôle d'attitude : volets, becs, aérofreins, spoilers, trims.</li></ul>"}, {"t": "Manuelle, assistée, asservie", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Commande</th>\n<th>Principe</th>\n<th>Ressenti</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Manuelle</strong></td>\n<td>Câbles, bielles, guignols</td>\n<td><strong>Réversible</strong> : le pilote sent les efforts ; simple, léger, fiable ; trop dur à grande vitesse</td></tr>\n<tr>\n<td><strong>Assistée</strong> (partiellement)</td>\n<td>Servocommande hydraulique + liaison mécanique gardée</td>\n<td><strong>Réversible</strong> : pas besoin de sensation artificielle ; pilotage manuel possible si l'assistance lâche</td></tr>\n<tr>\n<td><strong>Totalement asservie</strong></td>\n<td>Vérins hydrauliques ou électriques, sans retour</td>\n<td><strong>Irréversible</strong> : il faut une <strong>sensation artificielle</strong></td></tr></tbody></table>\n<ul>\n<li><strong>Irréversibilité</strong> : les efforts aérodynamiques ne remontent pas au manche (transmission à sens unique), ce qui protège aussi du flutter.</li>\n<li><strong>Q-feel</strong> : effort au manche proportionnel à la <strong>pression dynamique q</strong>, donc à la vitesse → évite la sur-commande à grande vitesse.</li>\n<li><strong>Trims en commandes asservies</strong> : plan horizontal réglable (<strong>THS</strong>) par vérin à vis ; les trims de direction et d'ailerons <strong>déplacent le neutre de l'unité de sensation</strong>. Pas besoin de tab aérodynamique.</li></ul>"}, {"t": "Sécurités des commandes primaires", "kind": "info", "html": "<ul>\n<li><strong>Composants</strong> : vérins, servovalves, câbles (sensibles au mou et à la tension), câblage, capteurs de position.</li>\n<li><strong>Redondance</strong> : 2 à 4 circuits indépendants, gouvernes divisées (intérieure et extérieure), modes de secours.</li>\n<li><strong>Blocage</strong> (câble cassé, corps étranger, fuite) : manches <strong>découplables</strong> (ATR 72 : découplage en tangage), câbles doublés, vérins séparés.</li>\n<li><strong>Blocages au sol</strong> (gust locks) contre le vent ; voyants et flammes ; à retirer avant le vol.</li>\n<li><strong>Limiteur de direction</strong> : réduit le débattement à grande vitesse pour protéger la dérive :<ul>\n<li><strong>rapport variable</strong> : la gouverne bat moins, le palonnier garde sa course ;</li>\n<li><strong>butées variables</strong> : la course du palonnier est limitée ;</li>\n<li><strong>blow-back</strong> : l'effort aérodynamique limite lui-même le débattement.</li></ul></li></ul>"}, {"t": "Les commandes secondaires", "kind": "info", "html": "<ul>\n<li><strong>Volets</strong> (bord de fuite) : plus de courbure, plus de portance. <strong>Becs</strong> (bord d'attaque) : retardent le décrochage, autorisent une incidence plus forte.</li>\n<li><strong>Aérofreins</strong> : traînée en descente. <strong>Spoilers en vol</strong> : aident le roulis + traînée. <strong>Spoilers sol</strong> : détruisent la portance au toucher.</li>\n<li><strong>Trims</strong> : tabs sur les gouvernes, ou plan horizontal réglable entier (THS).</li>\n<li><strong>Commande</strong> : hydraulique (le plus courant), pneumatique, électrique, mécanique, ou par l'écoulement (becs automatiques). Souvent irréversible, plus lente que les primaires.</li>\n<li><strong>Frein mécanique</strong> sur moteur hydraulique : bloque le vérin à vis sans pression (les volets ne glissent pas).</li>\n<li><strong>VFE</strong> = vitesse max volets sortis, une par cran.</li>\n<li><strong>Load relief</strong> : au-delà de VFE + marge, les volets <strong>remontent</strong> d'un cran tout seuls.</li>\n<li><strong>Protection dissymétrie</strong> : capteurs sur l'arbre de transmission ; si les volets sortent de façon inégale, le système <strong>se fige</strong> (sinon embardée en roulis et torsion de structure).</li>\n<li><strong>Becs automatiques</strong> : sortent seuls à forte incidence (ressort ou capteur d'incidence).</li>\n<li><strong>Blow-back</strong> : à grande vitesse, l'effort aéro dépasse celui du vérin et la surface rentre un peu. Protection naturelle.</li></ul>"}, {"t": "Les commandes électriques (FBW)", "kind": "info", "html": "<ul>\n<li><strong>Chaîne</strong> : manche ou mini-manche → capteurs → <strong>calculateurs</strong> → vérins → gouvernes, avec un retour des capteurs (anémométrie, centrale inertielle, positions) en <strong>boucle fermée</strong>.</li>\n<li><strong>Avantages</strong> : moins de travail (trim automatique, stabilité augmentée), <strong>protection du domaine de vol</strong> (décrochage, facteur de charge, assiette, inclinaison), gain de masse, permet un avion <strong>instable</strong> (moins de traînée, moins de carburant).</li>\n<li><strong>Irréversible</strong> : sensation artificielle par ressorts dans le mini-manche.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Loi</th>\n<th>Protections</th>\n<th>Charge pilote</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Normale</strong></td>\n<td>Toutes</td>\n<td>La plus faible</td></tr>\n<tr>\n<td><strong>Alternate</strong></td>\n<td>Partielles (par exemple plus de protection contre le décrochage), stabilité en partie gardée</td>\n<td>Plus forte</td></tr>\n<tr>\n<td><strong>Directe</strong></td>\n<td>Aucune : le manche commande la gouverne proportionnellement</td>\n<td>Maximale, dernier recours</td></tr></tbody></table>\n<ul>\n<li>Passage en loi dégradée = alerte ECAM/EICAS ; risque de sortir du domaine de vol.</li></ul>"}, {"t": "Mini-manches, calculateurs, capteurs", "kind": "info", "html": "<ul>\n<li><strong>Double action</strong> sur les mini-manches : les ordres sont <strong>additionnés</strong> (avec limite) + annonce « <strong>DUAL INPUT</strong> ».</li>\n<li><strong>Bouton de priorité</strong> : annule l'autre mini-manche + annonce « <strong>PRIORITY LEFT / RIGHT</strong> ».</li>\n<li><strong>Calculateurs dissemblables</strong> (matériels et logiciels différents) : un même bug ne touche pas tout ; logique de vote.</li>\n<li><strong>Capteurs critiques au moins triplés</strong> (incidence, vitesse, attitude), indépendants physiquement et électriquement ; le vote élimine le capteur faux.</li>\n<li><strong>Plusieurs gouvernes par axe</strong> : le contrôle reste possible si un vérin lâche, et les efforts sont répartis.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Volets, becs et trims sont <strong>secondaires</strong>.</li>\n<li><strong>Assistée</strong> = réversible, pas besoin de sensation artificielle. <strong>Asservie</strong> = irréversible, sensation artificielle obligatoire.</li>\n<li>Le <strong>load relief</strong> rentre les volets ; il ne les bloque pas.</li>\n<li>En <strong>loi directe</strong>, il n'y a <strong>plus aucune protection</strong>.</li>\n<li>Double action = ordres <strong>additionnés</strong>, pas annulés.</li></ul>"}], "oral": ["Définis commandes primaires et secondaires et cite les gouvernes de chaque axe.", "Compare commandes manuelles, assistées et asservies. Pourquoi une sensation artificielle est-elle nécessaire ?", "Comment fonctionne le trim sur une commande asservie ?", "Cite les protections des commandes secondaires (load relief, dissymétrie, becs automatiques, blow-back).", "Décris la chaîne d'une commande électrique et ses avantages.", "Compare les lois normale, alternate et directe.", "Pourquoi utilise-t-on des calculateurs dissemblables et des capteurs triplés ?"]}, "pressu": {"cards": [{"t": "L'air sur un avion à pistons", "kind": "info", "html": "<ul>\n<li><strong>Compresseur</strong> (pression positive) : gonfle les <strong>boudins de dégivrage</strong>, peut alimenter les gyros. Meilleur en altitude. Risque : <strong>contamination des instruments par l'huile</strong> de la pompe (les systèmes récents ont des pompes sèches).</li>\n<li><strong>Pompe à vide</strong> (à palettes, aspiration) : alimente les <strong>gyroscopes</strong> (horizon, conservateur de cap) avec de l'air propre. <strong>Moins efficace en altitude</strong>.</li>\n<li><strong>Chauffage cabine</strong> : par un <strong>échangeur autour du pot d'échappement</strong>, pas par l'air pneumatique. Risque : <strong>monoxyde de carbone</strong>.</li></ul>"}, {"t": "L'air prélevé sur un réacteur (bleed)", "kind": "info", "html": "<ul>\n<li><strong>Sources</strong> : étages <strong>HP</strong> et <strong>IP</strong> du compresseur, <strong>APU</strong>, groupe de parc.</li>\n<li><strong>Usages</strong> : antigivrage de la voilure et des entrées d'air, <strong>démarreur pneumatique</strong>, pressurisation des réservoirs hydrauliques, pompes hydrauliques à air, <strong>pressurisation et climatisation</strong>.</li>\n<li><strong>Composants</strong> : conduites, <strong>vanne d'intercommunication</strong> (cross-bleed), vanne de régulation de pression, vanne de prélèvement (choix HP ou IP selon N1), <strong>prérefroidisseur</strong> (échangeur avec l'air de soufflante), capteurs de pression et de température.</li>\n<li><strong>Règle</strong> : <strong>HP à bas régime</strong>, <strong>IP à fort régime</strong> (pour limiter la pénalité sur le moteur).</li>\n<li><strong>Indications</strong> : pression et température bleed, positions des vannes, page ECAM, alarmes OVERPRESS, BLEED LEAK.</li>\n<li><strong>Pannes</strong> : surchauffe (feu), surpression (conduite qui éclate), pression basse (plus d'antigivrage), <strong>fuite</strong> → feu de compartiment, perte de pressurisation. Action : <strong>isoler</strong> le prélèvement.</li></ul>"}, {"t": "Le principe de la pressurisation", "kind": "info", "html": "<ul>\n<li><strong>Trois paramètres</strong> sont réglés : <strong>ventilation</strong> (air frais + recirculation), <strong>température</strong>, <strong>pression</strong> (altitude cabine compatible avec la physiologie).</li>\n<li>L'<strong>humidité</strong> n'est pas régulée : 2 à 15 % en croisière (air de prélèvement très sec), sauf humidification sur A350 et 787. Le séparateur d'eau du bootstrap retire l'eau condensée.</li>\n<li><strong>Principe</strong> : le débit d'air <strong>entrant</strong> est à peu près <strong>constant</strong> ; la <strong>vanne de décharge</strong> (outflow valve) règle la sortie. <strong>Pression cabine = équilibre entre ce qui entre et ce qui sort.</strong> Fermer la vanne → la cabine « descend ».</li>\n<li><strong>Régulateur</strong> (souvent 2, électroniques) : reçoit l'altitude avion, la vitesse verticale et <strong>l'altitude du terrain de destination</strong> ; il calcule un programme et commande le moteur de la vanne. Vario cabine typique : <strong>500 à 1 000 ft/min</strong>.</li>\n<li><strong>Soupapes de sécurité</strong> (passives, indépendantes du régulateur) : <strong>surpression</strong> (ΔP trop fort, limite structurale) et <strong>dépression</strong> (cabine plus basse que l'extérieur : évite l'implosion).</li></ul>"}, {"t": "Les chiffres de la cabine", "kind": "info", "html": "<ul>\n<li><strong>Altitude cabine</strong> = altitude équivalente de la pression dans la cabine. <strong>Vario cabine</strong> = vitesse de variation de cette altitude.</li>\n<li><strong>ΔP = pression cabine − pression extérieure</strong>. <strong>Pressurisation au sol</strong> : avant le décollage.</li>\n<li>Altitude cabine ≤ <strong>8 000 ft</strong> en croisière (6 000 à 8 000 ft) ; 10 000 ft en secours.</li>\n<li><strong>Alarme à 10 000 ft cabine</strong> (Master Caution, alarme sonore, ECAM CAB ALT).</li>\n<li><strong>Masques passagers vers 14 000 ft</strong>.</li>\n<li><strong>ΔP max</strong> : 8,6 à 9,1 psi sur les gros jets. Le <strong>plafond de l'avion</strong> est limité par ce ΔP structural (ex. 8,6 psi → FL410 à 430).</li>\n<li><strong>Secours</strong> : commande <strong>manuelle</strong> de la vanne de décharge (QRH), en surveillant altitude cabine et ΔP.</li>\n<li><strong>Indications</strong> : altitude cabine, vario cabine, ΔP, température, état des packs, position de la vanne.</li></ul>"}, {"t": "Le cycle à air bootstrap", "kind": "info", "html": "<p>Le froid vient de la <strong>détente</strong> d'un air comprimé, sans fluide frigorigène (plus léger et fiable).\n1. Air de prélèvement <strong>chaud et comprimé</strong>.\n2. <strong>Prérefroidisseur</strong> (air de soufflante).\n3. <strong>Compresseur</strong> de l'ACM : l'air est encore comprimé et réchauffé.\n4. <strong>Échangeur principal</strong>, refroidi par l'air dynamique (ram air).\n5. <strong>Turbine</strong> de l'ACM : <strong>détente</strong>, l'air devient très froid. La turbine entraîne le compresseur.\n6. <strong>Séparateur d'eau</strong> (cyclone).\n7. Vers la cabine.</p>\n<p><strong>Pourquoi recomprimer l'air avant l'échangeur ?</strong> Plus l'air est chaud, mieux l'échangeur évacue la chaleur vers l'air extérieur ; ensuite la détente dans la turbine fait chuter la température bien plus bas.</p>"}, {"t": "Autour du pack", "kind": "info", "html": "<ul>\n<li><strong>Ventilateur</strong> du pack : fournit l'air de refroidissement au sol. <strong>Volet d'air dynamique</strong> : règle l'entrée d'air extérieur. <strong>Vanne de débit</strong> : règle l'air de prélèvement qui entre. Chaque pack est indépendant.</li>\n<li><strong>Vannes de mélange</strong> : mélangent l'air froid du pack et l'air chaud. <strong>Vannes d'isolement</strong> : coupent un pack en panne.</li>\n<li><strong>Recirculation</strong> : ~<strong>50 %</strong> de l'air, par des ventilateurs et des filtres HEPA (économie d'énergie, confort).</li>\n<li><strong>Hot trim air</strong> : air chaud qui <strong>contourne le pack</strong>, injecté zone par zone (cockpit, cabine avant, cabine arrière) pour régler chaque température.</li>\n<li><strong>Clim électrique</strong> (787, A350) : compresseurs électriques, <strong>pas de prélèvement</strong> → meilleure consommation, mais gros moteurs électriques et refroidissement plus complexes.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>La vanne de décharge est en <strong>sortie</strong> : le débit entrant reste à peu près constant.</li>\n<li><strong>Alarme 10 000 ft</strong>, masques <strong>14 000 ft</strong>, croisière <strong>≤ 8 000 ft</strong>.</li>\n<li>Le froid du bootstrap vient de la <strong>turbine</strong> (détente), pas du compresseur.</li>\n<li>Hot trim air : il <strong>contourne</strong> le pack.</li>\n<li>HP à <strong>bas</strong> régime, IP à <strong>fort</strong> régime.</li>\n<li>La pompe à vide perd en efficacité en <strong>altitude</strong> ; le compresseur, lui, y est meilleur.</li></ul>"}], "oral": ["Compare compresseur et pompe à vide sur un avion à pistons. Quel est le risque du chauffage cabine ?", "Cite les sources et les usages de l'air prélevé. Pourquoi prélève-t-on en HP à bas régime ?", "Explique le principe de la pressurisation et le rôle du régulateur et des soupapes de sécurité.", "Définis altitude cabine, vario cabine et pression différentielle. Donne les valeurs limites et les alarmes.", "Décris les étapes du cycle bootstrap et explique d'où vient le froid.", "À quoi sert le hot trim air ? Quel est l'intérêt d'une climatisation électrique ?"]}, "oxygivre": {"cards": [{"t": "L'oxygène équipage", "kind": "info", "html": "<p>Un régulateur <strong>diluteur à la demande</strong> relié à une bouteille haute pression (ou un générateur chimique). Objectif : éviter l'<strong>hypoxie</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>Mode</th>\n<th>Fonction</th>\n<th>Quand</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Normal</strong> (dilution)</td>\n<td>Mélange air cabine + O₂ ; plus d'O₂ en montant</td>\n<td>Altitude cabine &gt; 10 000 ft ; le plus économe</td></tr>\n<tr>\n<td><strong>100 %</strong></td>\n<td>O₂ pur</td>\n<td><strong>Fumée</strong>, ou au-dessus de ~25 000 à 30 000 ft cabine</td></tr>\n<tr>\n<td><strong>Emergency</strong></td>\n<td>O₂ en <strong>surpression</strong> : poussé dans les poumons</td>\n<td>Décompression rapide, très haute altitude cabine (35 000 à 40 000 ft)</td></tr></tbody></table>"}, {"t": "L'oxygène portable et passagers", "kind": "info", "html": "<ul>\n<li><strong>Cagoule anti-fumée (PBE)</strong> : générateur chimique intégré, <strong>15 à 20 min</strong>, protège les yeux et les voies respiratoires.</li>\n<li><strong>Bouteille portable</strong> : O₂ gazeux, à la demande ou en continu, <strong>10 à 30 min</strong> selon la taille et le débit.</li>\n<li><strong>Passagers, système fixe</strong> : surtout des <strong>générateurs chimiques</strong> (chlorate de sodium + un peu de peroxyde de baryum et de perchlorate de potassium), <strong>12 à 20 min</strong>, <strong>débit continu</strong>. Une fois lancé, il ne s'arrête plus. Certains avions ont un système gazeux central.</li>\n<li><strong>Chute des masques</strong> : automatique vers <strong>14 000 ft cabine</strong> (capsule anévroïde), ou manuelle (bouton MAN DROP). L'oxygène coule quand le passager <strong>tire le masque</strong>.</li>\n<li><strong>Danger</strong> : <strong>graisse ou huile + O₂ sous pression = inflammation spontanée</strong>, voire explosion. Jamais de produit pétrolier : seulement des lubrifiants compatibles oxygène, et des procédures de nettoyage strictes.</li></ul>"}, {"t": "Antigivrage ou dégivrage", "kind": "info", "html": "<ul>\n<li><strong>Antigivrage</strong> : empêche la glace de se former (surface chaude ou glace qui n'adhère pas). Protection <strong>continue</strong>. Préféré sur les surfaces critiques.</li>\n<li><strong>Dégivrage</strong> : laisse la glace se former, puis l'enlève par <strong>cycles</strong>.</li>\n<li><strong>Zones protégées</strong> : bords d'attaque des ailes et des empennages, entrées d'air moteur, hélices, pare-brise, sondes (Pitot, statiques, incidence, TAT), antennes critiques.</li>\n<li><strong>Empennage non protégé</strong> sur beaucoup de jets : il travaille dans un air plus « propre » derrière l'aile et l'avion est certifié ainsi. Risque : <strong>décrochage de l'empennage</strong>, surtout avec les volets sortis. Éviter les grosses variations de trim, la forte incidence et le givrage prolongé.</li></ul>"}, {"t": "Les systèmes de protection", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Système</th>\n<th>Principe</th>\n<th>Type</th>\n<th>Usage</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Air chaud</strong></td>\n<td>Air prélevé à 200 à 350 °C, réparti par des <strong>tubes piccolo</strong> au bord d'attaque</td>\n<td>Anti (continu)</td>\n<td>Jets : voilure, nacelles</td></tr>\n<tr>\n<td><strong>Électrique</strong></td>\n<td>Résistances noyées : faible puissance continue = anti ; impulsions fortes = dé</td>\n<td>Anti ou dé</td>\n<td>Hélices, pare-brise, sondes, petits bords d'attaque</td></tr>\n<tr>\n<td><strong>Fluide</strong></td>\n<td>Liquide glycolé par un bord d'attaque poreux ou une bague d'hélice : abaisse le point de congélation</td>\n<td>Anti</td>\n<td>Petits turbopropulseurs, aviation légère</td></tr>\n<tr>\n<td><strong>Boudins</strong></td>\n<td>Caoutchouc gonflé puis dégonflé : la glace casse et part. Cycles de 6 à 60 s ; laisser 6 à 13 mm de glace</td>\n<td><strong>Dé seulement</strong></td>\n<td>Turbopropulseurs, avions à pistons</td></tr></tbody></table>\n<ul>\n<li><strong>Pare-brise</strong> : désembuage par air chaud à l'intérieur sur la plupart des avions ; pare-brise <strong>chauffant</strong> (fils ou film conducteur) maintenu entre <strong>18 et 35 °C</strong>, alimenté en <strong>AC triphasé 400 Hz</strong>.</li>\n<li><strong>Limites</strong> : air chaud = pénalité moteur (régime mini) ; boudins limités par la pompe ; fluide limité en quantité ; température mini et TAT max d'efficacité.</li></ul>"}, {"t": "L'exemple A320", "kind": "info", "html": "<ul>\n<li><strong>Conditions givrantes</strong> : OAT (au sol, au décollage) ou TAT (en vol) <strong>≤ 10 °C</strong> <strong>+ humidité visible</strong> (nuages, brouillard ≤ 1 mile, pluie, neige, grésil, cristaux de glace). Aussi au sol avec OAT ≤ 10 °C sur une piste avec neige, eau ou slush.</li>\n<li><strong>Antigivrage moteur</strong> : ON dès qu'il y a ou qu'on prévoit des conditions givrantes, <strong>sauf en montée et en croisière avec SAT &lt; −40 °C</strong>. Mais <strong>toujours ON en descente</strong> dans le givrage, même sous −40 °C.</li>\n<li><strong>Antigivrage voilure</strong> : pour prévenir ou enlever la glace ; ON dès qu'il y a du givre sur l'<strong>indicateur visuel</strong> (entre les deux pare-brise) ou sur les essuie-glaces.</li></ul>"}, {"t": "Les détecteurs de givre", "kind": "info", "html": "<p>Ils détectent le <strong>début</strong> du givrage, pas une épaisseur. Placés à l'avant du fuselage ou au bord d'attaque.</p>\n<table>\n<thead>\n<tr>\n<th>Détecteur</th>\n<th>Principe</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Pneumatique</strong> (Smiths)</td>\n<td>Trous face au vent ; la glace les bouche → le capteur voit la statique → <strong>chute de pression</strong> → manocontact. Un réchauffeur dégage d'abord les trous et éteint l'alarme</td></tr>\n<tr>\n<td><strong>Rotatif</strong></td>\n<td>Rotor tournant contre un couteau (jeu 0,05 mm). La glace bloque le jeu → <strong>couple</strong> qui fait pivoter le moteur sur ses silentblocs → microcontact</td></tr>\n<tr>\n<td><strong>À résonance</strong> (Rosemount, le plus courant)</td>\n<td>Sonde magnétostrictive vibrant vers <strong>40 kHz</strong>. La masse de glace <strong>fait baisser la fréquence</strong>. Un bref chauffage confirme que c'est de la glace et pas de l'eau (voyant ICE qui clignote)</td></tr></tbody></table>\n<p><strong>L'alarme</strong> : voyant ICE ambre, message ECAM, parfois un son, parfois l'activation automatique de l'antigivrage. Elle reste tant que la sonde n'est pas dégagée.</p>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Une alarme <strong>ICE</strong> veut dire « <strong>de la glace se forme</strong> », <strong>pas</strong> « la protection est en marche » : l'équipage doit agir.</li>\n<li>Les <strong>boudins</strong> font <strong>seulement du dégivrage</strong>.</li>\n<li>À résonance : la glace <strong>baisse</strong> la fréquence.</li>\n<li>Masques passagers : <strong>débit continu</strong>, générateur qui ne s'arrête plus. Masque équipage : <strong>à la demande</strong>.</li>\n<li>Mode <strong>100 %</strong> contre la <strong>fumée</strong> ; mode <strong>Emergency</strong> = surpression.</li>\n<li>A320 : sous −40 °C de SAT, l'antigivrage moteur n'est pas obligatoire en <strong>montée et croisière</strong>, mais il l'est <strong>en descente</strong>.</li></ul>"}], "oral": ["Décris les trois modes du masque équipage et leur usage.", "Comment fonctionne l'oxygène passagers ? Pourquoi la graisse est-elle interdite sur un circuit oxygène ?", "Différencie antigivrage et dégivrage. Quelles zones protège-t-on ? Pourquoi certains empennages ne le sont pas ?", "Compare les protections par air chaud, électrique, fluide et boudins.", "Donne la définition A320 des conditions givrantes et les règles d'usage de l'antigivrage moteur.", "Explique le principe des trois types de détecteurs de givre."]}, "carburant": {"cards": [{"t": "Les carburants", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Carburant</th>\n<th>Point éclair</th>\n<th>Congélation</th>\n<th>Densité (kg/L)</th>\n<th>Remarques</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>AVGAS 100LL</strong></td>\n<td>≈ −40 °C</td>\n<td>≈ −58 °C</td>\n<td>0,68 à 0,72</td>\n<td>Allumage commandé ; octane élevé contre le cliquetis ; risque de <strong>vapour lock</strong></td></tr>\n<tr>\n<td><strong>MOGAS</strong></td>\n<td>≈ −45 à −38 °C</td>\n<td>−50 à −60 °C</td>\n<td>0,73 à 0,77</td>\n<td>Seulement si approuvé ; éthanol corrosif, vapour lock, givrage carbu plus probable</td></tr>\n<tr>\n<td><strong>JET A</strong></td>\n<td>≥ 38 °C</td>\n<td>≤ −40 °C</td>\n<td>0,775 à 0,84</td>\n<td>Kérosène, surtout aux États-Unis</td></tr>\n<tr>\n<td><strong>JET A-1</strong></td>\n<td>≥ 38 °C</td>\n<td><strong>≤ −47 °C</strong></td>\n<td>0,775 à 0,84</td>\n<td>Standard mondial ; additifs antistatique et anticorrosion ; aussi pour les <strong>diesels</strong> d'avion</td></tr>\n<tr>\n<td><strong>JET B</strong></td>\n<td>≈ −20 à −10 °C</td>\n<td>≤ −50 à −60 °C</td>\n<td>≈ 0,78</td>\n<td>30 % essence + 70 % kérosène ; grand froid ; <strong>très volatil</strong></td></tr></tbody></table>\n<ul>\n<li><strong>FSII</strong> (DiEGME, Prist) : empêche les cristaux de glace de l'eau contenue dans le carburant ; 0,10 à 0,15 % en volume ; aussi antibactérien. <strong>JP-8 = Jet A-1 + FSII</strong>.</li>\n<li><strong>Jet A-1 dans un diesel</strong> (Austro AE300, Continental CD-155) : peu volatil → démarrage à froid difficile.</li>\n<li>La <strong>densité</strong> sert à convertir litres et kilos (masse et centrage, autonomie).</li></ul>"}, {"t": "Le circuit carburant d'un avion léger", "kind": "info", "html": "<ul>\n<li><strong>Missions</strong> : stocker assez de carburant ; alimenter le moteur en carburant <strong>propre et continu</strong> dans toutes les attitudes ; permettre l'équilibrage ; indiquer la quantité ; éviter contamination et vapour lock ; permettre purge et prélèvement.</li>\n<li><strong>Composants</strong> :<ul>\n<li>conduites rigides (alu) et flexibles ;</li>\n<li><strong>pompe de gavage</strong> électrique (boost) : pression positive vers la pompe moteur ; indispensable au démarrage, par temps chaud, en secours ;</li>\n<li>clapets anti-retour, soupapes ; filtres (by-pass s'ils se bouchent) ;</li>\n<li><strong>mise à l'air libre</strong> : laisse entrer et sortir l'air (évite dépression et surpression) ;</li>\n<li><strong>puisard</strong> (point bas : eau et dépôts) et <strong>purge</strong> (contrôle d'eau quotidien par le pilote) ;</li>\n<li>jauges (flotteur, capacitive, ultrasons) et sonde de température.</li></ul></li>\n<li><strong>Alimentation par gravité</strong> : réservoir au-dessus du moteur, sans pompe (aile haute). Simple et fiable.</li>\n<li><strong>Alimentation sous pression</strong> : pompe de gavage + pompe moteur. Marche en altitude, par temps chaud, sur le dos ; mais dépend de l'électricité et de la mécanique.</li></ul>"}, {"t": "Réservoirs, cross-feed, carburant inutilisable", "kind": "info", "html": "<ul>\n<li><strong>Réservoirs</strong> : rigides (inspectables), <strong>souples</strong> (bladder, étanches ; mais des plis au fond peuvent piéger de l'eau et du carburant inutilisable), <strong>structuraux</strong> (l'aile elle-même : légers et efficaces).</li>\n<li><strong>Intercommunication</strong> (cross-feed) : alimenter un moteur avec le réservoir <strong>opposé</strong>, pour équilibrer, en monomoteur, ou après une panne moteur. En général manuelle : vérifier la symétrie après.</li>\n<li><strong>Carburant inutilisable</strong> : la quantité qui ne peut pas atteindre le moteur dans le pire cas (dans les puisards, les tuyaux, au-dessus de la crépine en montée forte). Donnée par le manuel de vol, <strong>pas affichée par la jauge</strong>, à retirer pour l'autonomie.</li>\n<li><strong>Surveillance</strong> : quantité + <strong>alarme niveau bas</strong> (vers 30 à 60 min restantes, souvent par un capteur séparé) ; température (gel du Jet A-1, vapour lock) ; <strong>débitmètre</strong> (le massique est plus fiable que le volumique, car la densité varie).</li></ul>"}, {"t": "Le circuit carburant d'un avion à turbines", "kind": "info", "html": "<ul>\n<li><strong>Missions</strong> en plus : grandes quantités, avitaillement et vidange, <strong>équilibrage</strong> (réservoir de trim, cross-feed), alimentation de l'APU.</li>\n<li><strong>Pompes de gavage centrifuges</strong> immergées (refroidies par le carburant), doublées par réservoir ; <strong>vanne coupe-feu</strong> sur la cloison pare-feu ; filtres BP et HP.</li>\n<li><strong>Réservoirs</strong> : ailes (principaux), centre, saumons, <strong>queue (trim tank, pour le centrage)</strong>. <strong>Cloisons anti-ballottement</strong> avec clapets, pour garder le carburant aux points d'aspiration ; puisards, purges et pompes à jet qui aspirent l'eau ; mises à l'air libre avec réservoirs de surpression.</li>\n<li><strong>Jauges capacitives</strong>, indication en <strong>masse</strong> (corrige la variation de densité). Une sonde en panne affiche <strong>vide</strong>.</li>\n<li><strong>Perte des pompes de gavage</strong> : la pompe moteur cavite, risque d'<strong>extinction en altitude</strong> → <strong>descendre</strong>, réduire la puissance, gravité si possible. Alarme LOW FUEL PRESS.</li>\n<li><strong>Jaugeurs à tige magnétique</strong> (drip sticks) sous l'aile : un flotteur aimanté, on lit la tige → vérifier les jauges au sol.</li>\n<li><strong>Vidange en vol</strong> (dump) : seulement si la <strong>MTOM dépasse largement la MLM</strong> (long-courriers). Jusqu'à 2 à 3 t/min, au-dessus de 6 000 ft, loin des zones habitées, arrêt automatique à une masse préréglée.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Point éclair : AVGAS <strong>≈ −40 °C</strong> (très inflammable), Jet A-1 <strong>≥ 38 °C</strong>.</li>\n<li>Jet A-1 gèle à <strong>−47 °C</strong>, Jet A à <strong>−40 °C</strong>.</li>\n<li>Le carburant inutilisable <strong>n'est pas affiché</strong> par la jauge.</li>\n<li>Jauge capacitive en panne = affiche <strong>vide</strong>.</li>\n<li>Perte des pompes de gavage → <strong>descendre</strong> (air plus dense, moins de cavitation).</li>\n<li>Le dump n'existe que si MTOM ≫ MLM.</li></ul>"}], "oral": ["Compare AVGAS, MOGAS, Jet A, Jet A-1 et Jet B (point éclair, congélation, densité, limites).", "Quelles sont les missions d'un circuit carburant ? Cite ses composants et leur rôle.", "Compare l'alimentation par gravité et sous pression.", "Qu'est-ce que le carburant inutilisable ? À quoi sert l'intercommunication ?", "Que se passe-t-il si les pompes de gavage tombent en panne en altitude, et que faut-il faire ?", "Quand un avion est-il équipé d'une vidange en vol ? Quelles précautions ?"]}, "elecbase": {"cards": [{"t": "L'électricité statique", "kind": "info", "html": "<ul>\n<li><strong>Origine</strong> : le frottement de l'avion contre l'air, les cristaux de glace, la poussière, la pluie, la neige (effet <strong>triboélectrique</strong>). La charge peut atteindre des dizaines à des centaines de kV.</li>\n<li><strong>Conditions les pires</strong> : haute altitude (FL250 à FL410), <strong>cristaux de glace et neige</strong> (cirrus, enclumes), précipitations, air sec, <strong>grande vitesse vraie</strong>, sommets d'orage.</li>\n<li><strong>Déperditeurs statiques</strong> (static wicks) : ils déchargent l'électricité par <strong>effet couronne</strong> contrôlé, à basse tension. Placés aux <strong>bords de fuite</strong> des ailes et des empennages (6 à 12 par avion), en fibre de carbone ou en fils résistifs.</li>\n<li><strong>Ils évitent</strong> : les parasites radio (P-static), les étincelles aux mises à l'air libre ou pendant l'avitaillement, les dégâts aux antennes et à l'avionique, et au pire le soudage des articulations de gouvernes.</li>\n<li><strong>Prévol</strong> : tous présents, intacts, propres. Il en manque un → risque de parasites radio.</li></ul>"}, {"t": "Mise à la terre et métallisation", "kind": "info", "html": "<ul>\n<li><strong>Avant l'avitaillement</strong> : l'avion peut être encore chargé, et le carburant qui coule dans les tuyaux se charge aussi. Une différence de potentiel = une étincelle = les vapeurs s'enflamment.</li>\n<li><strong>Ordre</strong> : <strong>1. câble de masse</strong>, <strong>2. pistolet ou tuyau</strong>, <strong>3. avitaillement</strong>.</li>\n<li><strong>Métallisation</strong> (bonding) : toutes les pièces conductrices sont reliées pour être au <strong>même potentiel</strong> (structure, réservoirs, tuyaux, antennes, sondes). Elle évite les étincelles à l'intérieur des réservoirs et aux jonctions.</li>\n<li>Métallisation + déperditeurs = protection complète contre la statique.</li></ul>"}, {"t": "Le courant continu", "kind": "info", "html": "<ul>\n<li><strong>Continu</strong> = le courant circule <strong>dans un seul sens</strong>, la polarité ne change pas. Il ne passe que dans un <strong>circuit fermé</strong>. Sources : batteries, génératrices, alternatif redressé.</li>\n<li><strong>Conducteurs</strong> (électrons libres : cuivre, aluminium), <strong>semi-conducteurs</strong> (silicium), <strong>isolants</strong> (PVC).</li>\n<li><strong>Tension</strong> U en <strong>volts</strong> : la « pression » qui pousse les électrons. <strong>Intensité</strong> I en <strong>ampères</strong> : le « débit ».</li>\n<li><strong>Loi d'Ohm</strong> : <strong>U = R × I</strong>. Plus de tension → plus de courant ; plus de résistance → moins de courant.</li>\n<li><strong>Puissance</strong> : <strong>P = U × I = R × I² = U² / R</strong>, en watts. Elle sert à dimensionner les fils, les fusibles, les disjoncteurs et les batteries.</li></ul>\n<p><strong>Exemple</strong> : 28 V sur une résistance de 14 Ω → I = 28 / 14 = <strong>2 A</strong>, et P = 28 × 2 = <strong>56 W</strong>.</p>"}, {"t": "Série, parallèle, CTP et CTN", "kind": "info", "html": "<ul>\n<li><strong>En série</strong> : R totale = R1 + R2 + R3. Le <strong>même courant</strong> traverse tout, la <strong>tension se partage</strong>.</li>\n<li><strong>En parallèle</strong> : 1/R = 1/R1 + 1/R2 + 1/R3. La R totale <strong>diminue</strong>, la <strong>même tension</strong> est aux bornes de chaque branche, le <strong>courant se partage</strong> et le courant total <strong>augmente</strong>.</li>\n<li><strong>Exemples</strong> : deux 10 Ω en série = 20 Ω ; en parallèle = <strong>5 Ω</strong>.</li>\n<li><strong>CTP</strong> (PTC) : la résistance <strong>augmente</strong> avec la température → fusibles réarmables, capteurs.</li>\n<li><strong>CTN</strong> (NTC) : la résistance <strong>diminue</strong> avec la température → limiteur de courant d'appel, thermistance de mesure.</li>\n<li><strong>Interrupteurs</strong> : à levier, à bascule, poussoir, rotatif. Les <strong>interrupteurs protégés</strong> par un capot évitent une action par erreur sur un système critique (pompes, extincteurs, démarrage).</li></ul>"}, {"t": "Le courant alternatif", "kind": "info", "html": "<ul>\n<li><strong>Alternatif</strong> = le courant change de sens régulièrement, en forme de <strong>sinusoïde</strong>. Produit par des alternateurs ou des onduleurs. Plus complexe à bord que le continu, mais bien meilleur pour produire et distribuer de fortes puissances.</li>\n<li><strong>Phase</strong> = la position dans le cycle (0 à 360°). <strong>Déphasage</strong> = l'écart angulaire entre deux signaux de même fréquence : 0° en phase, <strong>120°</strong> en triphasé, 180° en opposition.</li>\n<li><strong>Triphasé</strong> : 3 tensions décalées de 120° → <strong>puissance constante</strong>, moteurs plus simples, plus légers et plus efficaces, câbles mieux utilisés.</li>\n<li><strong>Standard avion</strong> : <strong>115/200 V, 400 Hz</strong>. 115 V entre une phase et le neutre, 200 V entre deux phases. Monophasé 115 V pour les petites charges.</li>\n<li><strong>Fréquence</strong> = nombre de cycles par seconde, en <strong>hertz</strong>. <strong>Pourquoi 400 Hz ?</strong> Transformateurs et moteurs <strong>beaucoup plus petits et légers</strong>.</li>\n<li>Pour coupler deux alternateurs, le déphasage doit être <strong>nul</strong>, sinon courants de circulation énormes et dégâts.</li></ul>"}, {"t": "L'électromagnétisme", "kind": "info", "html": "<ul>\n<li>Tout courant crée un <strong>champ magnétique</strong> autour du fil (règle de la main droite). Le champ est <strong>proportionnel au courant</strong>, et au <strong>nombre de spires</strong> pour une bobine ; il diminue avec la distance.</li>\n<li><strong>Solénoïde</strong> : bobine + noyau mobile attiré dans la bobine → <strong>mouvement linéaire</strong> ; un ressort le ramène. Usage : vannes carburant, sélecteurs hydrauliques.</li>\n<li><strong>Relais</strong> : une petite bobine (petit courant) attire une palette qui ferme de <strong>gros contacts</strong> → on commande un circuit de puissance à distance, avec deux circuits isolés. Usage : bus tie, contrôle des génératrices.</li>\n<li><strong>Induction</strong> (loi de Faraday) : un <strong>flux magnétique variable</strong> induit une tension, proportionnelle à la vitesse de variation. Deux cas : un conducteur qui tourne dans un champ (<strong>génératrice</strong>), ou un courant variable dans une bobine qui induit une tension dans une bobine voisine (<strong>transformateur</strong>, induction mutuelle, sans contact).</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>En <strong>parallèle</strong>, la résistance totale <strong>baisse</strong> et le courant total <strong>augmente</strong>.</li>\n<li><strong>CTP</strong> : la résistance monte avec la chaleur ; <strong>CTN</strong> : elle baisse.</li>\n<li>Avitaillement : <strong>masse d'abord</strong>.</li>\n<li>Déperditeurs aux <strong>bords de fuite</strong>, pas aux bords d'attaque.</li>\n<li>Triphasé : <strong>120°</strong> entre phases. 115 V phase-neutre, <strong>200 V</strong> entre phases.</li></ul>"}], "oral": ["D'où vient l'électricité statique ? Dans quelles conditions est-elle maximale ? À quoi servent les déperditeurs ?", "Pourquoi met-on l'avion à la masse avant l'avitaillement ? À quoi sert la métallisation ?", "Énonce la loi d'Ohm et la formule de la puissance. Calcule I et P pour 28 V sur 7 Ω.", "Compare un montage en série et en parallèle.", "Qu'est-ce qu'une résistance CTP et une CTN ? Donne un usage de chacune.", "Définis phase, déphasage et fréquence. Pourquoi les avions utilisent-ils du triphasé 400 Hz ?", "Explique le principe du solénoïde, du relais et de l'induction."]}, "protections": {"cards": [{"t": "Fusibles et disjoncteurs", "kind": "info", "html": "<ul>\n<li><strong>Fusible</strong> : un fil fin qui <strong>fond</strong> quand le courant dépasse son calibre → circuit ouvert. À remplacer.</li>\n<li><strong>Disjoncteur</strong> (CB) : un interrupteur automatique qui <strong>s'ouvre</strong> en surintensité, et qui <strong>se réarme</strong>. Préféré en avion.</li>\n<li>Les deux protègent <strong>contre l'échauffement et le feu</strong> : ils protègent le <strong>câble</strong>.</li>\n<li><strong>Calibre</strong> en ampères. Fusible <strong>rapide</strong> (réagit vite au court-circuit) ou <strong>temporisé</strong> (tolère les pointes). Exemple : un fusible de 5 A saute vers 7 à 10 A selon la durée.</li>\n<li><strong>Jamais un calibre plus fort</strong> : le fil chaufferait et brûlerait <strong>avant</strong> que le fusible saute.</li></ul>"}, {"t": "Thermique ou magnétique", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Disjoncteur</th>\n<th>Déclenchement</th>\n<th>Vitesse</th>\n<th>Contre</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Thermique</strong></td>\n<td>Un <strong>bilame</strong> chauffe et se tord</td>\n<td><strong>Lent</strong>, dépend de la durée</td>\n<td>La <strong>surcharge</strong></td></tr>\n<tr>\n<td><strong>Magnétique</strong></td>\n<td>Une <strong>force électromagnétique</strong></td>\n<td><strong>Très rapide</strong></td>\n<td>Le <strong>court-circuit</strong></td></tr></tbody></table>\n<p>En avion, on combine souvent les deux (magnéto-thermique) : le magnétique coupe vite les courts-circuits, le thermique coupe les surcharges qui durent.</p>"}, {"t": "Le court-circuit et les surintensités", "kind": "info", "html": "<ul>\n<li><strong>Court-circuit</strong> : un chemin de résistance presque nulle entre le + et le −. Loi d'Ohm : <strong>I = U / R</strong> → si R ≈ 0, le courant devient énorme. Puissance : <strong>P = R × I²</strong> → même une petite résistance dégage une chaleur massive → fils qui chauffent, isolant qui fond, <strong>feu</strong>. C'est le principal risque de feu électrique.</li>\n<li><strong>Surintensité transitoire</strong> : un pic court et normal (démarrage d'un moteur électrique, foudre, coupure d'une charge inductive). Les fusibles temporisés et les thermiques la tolèrent ; les magnétiques coupent les vrais défauts. La protection doit faire la différence.</li></ul>"}, {"t": "Réarmer un disjoncteur", "kind": "info", "html": "<ul>\n<li>Beaucoup de procédures (QRH, ECAM) demandent de <strong>réarmer</strong> un disjoncteur pour relancer un calculateur, une pompe, un capteur après un défaut passager.</li>\n<li><strong>Séquence typique</strong> : tirer le disjoncteur, attendre <strong>10 à 30 s</strong>, le repousser.</li>\n<li><strong>Une seule fois</strong>, sauf procédure contraire. Réarmer plusieurs fois peut provoquer des arcs et de la surchauffe, et <strong>cacher un vrai défaut</strong> (un fil dénudé qui frotte).</li>\n<li><strong>Jamais de shunt</strong> (trombone, fusible ponté) : risque catastrophique.</li>\n<li>Le réarmement est une étape de dépannage, pas une réparation.</li></ul>"}, {"t": "Les semi-conducteurs et la chaleur", "kind": "info", "html": "<ul>\n<li>Les semi-conducteurs (silicium, germanium) <strong>conduisent mieux quand ils chauffent</strong> (comportement CTN).</li>\n<li><strong>Trop chaud</strong> : courants de fuite, faux basculements, gain réduit, <strong>emballement thermique</strong> (destruction), vieillissement accéléré.</li>\n<li><strong>Trop froid</strong> : commutation plus lente, chute de tension plus forte.</li>\n<li>D'où les ailettes, les dissipateurs, la <strong>ventilation des baies avioniques</strong> et la climatisation.</li></ul>"}, {"t": "Les portes logiques", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Porte</th>\n<th>Sortie = 1 quand…</th>\n<th>Symbole</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>ET</strong> (AND)</td>\n<td><strong>toutes</strong> les entrées = 1</td>\n<td>Forme en D à dos plat</td></tr>\n<tr>\n<td><strong>OU</strong> (OR)</td>\n<td><strong>au moins une</strong> entrée = 1</td>\n<td>Dos courbe</td></tr>\n<tr>\n<td><strong>NON</strong> (NOT)</td>\n<td>l'entrée = 0 (elle inverse)</td>\n<td>Triangle + petit rond</td></tr>\n<tr>\n<td><strong>NON-OU</strong> (NOR)</td>\n<td><strong>toutes</strong> les entrées = 0</td>\n<td>OU + petit rond</td></tr>\n<tr>\n<td><strong>NON-ET</strong> (NAND)</td>\n<td><strong>pas toutes</strong> à 1 (sortie 0 seulement si toutes = 1)</td>\n<td>ET + petit rond</td></tr></tbody></table>\n<ul>\n<li>Le <strong>petit rond</strong> (bulle) = une <strong>inversion</strong>.</li>\n<li>On lit un schéma de FCOM <strong>de gauche (entrées) à droite (sortie)</strong>.</li>\n<li><strong>Exemple</strong> : « SI train comprimé (WOW) <strong>ET</strong> manettes au ralenti → sortie des spoilers sol » : une porte ET avec deux entrées.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>Thermique</strong> = lent, surcharge ; <strong>magnétique</strong> = rapide, court-circuit.</li>\n<li>Le disjoncteur protège le <strong>câble</strong>, pas l'équipement.</li>\n<li><strong>Un seul</strong> réarmement, sauf procédure.</li>\n<li><strong>NAND</strong> : sortie à 0 <strong>seulement</strong> si toutes les entrées sont à 1. <strong>NOR</strong> : sortie à 1 <strong>seulement</strong> si toutes sont à 0.</li>\n<li>Un semi-conducteur chaud conduit <strong>plus</strong> (comme une CTN).</li></ul>"}], "oral": ["Compare fusible et disjoncteur. Pourquoi ne faut-il jamais monter un fusible de calibre supérieur ?", "Compare disjoncteur thermique et magnétique.", "Explique avec la loi d'Ohm et la formule de puissance pourquoi un court-circuit provoque un feu.", "Pourquoi ne réarme-t-on un disjoncteur qu'une seule fois ?", "Quel est l'effet de la température sur les semi-conducteurs ?", "Donne la table de vérité des portes ET, OU, NON, NON-ET et NON-OU."]}, "generation": {"cards": [{"t": "La batterie de bord", "kind": "info", "html": "<ul>\n<li><strong>Rôles</strong> : <strong>démarrer</strong> les moteurs et l'APU (gros courant) ; <strong>secours</strong> quand toutes les génératrices lâchent ; stabiliser la tension et absorber les pointes ; alimenter au sol sans groupe ; garder les mémoires et les horloges.</li>\n<li><strong>Types</strong> : <strong>plomb-acide</strong> (ancien), <strong>nickel-cadmium (Ni-Cd)</strong> (jets et turbopropulseurs anciens), <strong>lithium-ion</strong> (A350, 787, jets d'affaires : légère et dense en énergie), lithium-polymère (très rare en avion certifié).</li>\n<li><strong>C-rate</strong> : vitesse de charge ou de décharge par rapport à la capacité. <strong>1C</strong> = charge ou décharge complète en <strong>1 heure</strong>.</li></ul>"}, {"t": "Éléments, tension, capacité", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Tension d'un élément</th>\n<th>Pour 28 V</th></tr></thead>\n<tbody>\n<tr>\n<td>Plomb-acide</td>\n<td><strong>2,0 V</strong> (2,1 à 2,2 V chargé)</td>\n<td>—</td></tr>\n<tr>\n<td><strong>Ni-Cd</strong></td>\n<td><strong>1,2 V</strong></td>\n<td><strong>24 éléments</strong> (24 × 1,2 V)</td></tr>\n<tr>\n<td><strong>Lithium-ion</strong></td>\n<td><strong>3,6 à 3,7 V</strong> (4,2 V chargé)</td>\n<td><strong>7 à 8 éléments</strong></td></tr></tbody></table>\n<ul>\n<li><strong>En série</strong> : la <strong>tension</strong> s'additionne. <strong>En parallèle</strong> : la <strong>capacité</strong> s'additionne. La batterie correspond à la tension du bus 28 V DC.</li>\n<li><strong>Tension de charge toujours plus haute</strong> que la tension de la batterie, pour vaincre la résistance interne : plomb 28,5 à 28,8 V ; Ni-Cd 28 à 30 V (corrigée selon la température) ; lithium 4,2 V max par élément.</li>\n<li><strong>Capacité</strong> en <strong>ampères-heures (Ah)</strong> (parfois en Wh) : 40 Ah = 40 A pendant 1 h ou 4 A pendant 10 h, en théorie. 15 à 80 Ah selon l'avion. Réduite par un fort courant et par le froid.</li></ul>"}, {"t": "Température et autonomie", "kind": "info", "html": "<ul>\n<li><strong>Froid</strong> (&lt; 0 °C) : la chimie ralentit, <strong>40 à 60 % de capacité à −20 °C</strong>, résistance interne plus forte, la tension chute en charge. Démarrage à froid difficile : préchauffage ou groupe de parc.</li>\n<li><strong>Chaud</strong> (&gt; 40 °C) : un peu plus de capacité mais vieillissement accéléré, autodécharge, risque d'<strong>emballement thermique</strong> (surtout lithium).</li>\n<li><strong>Plage idéale</strong> : +15 à +30 °C.</li>\n<li><strong>Batterie seule</strong> (plus aucune génératrice) : autonomie <strong>limitée, 30 min à 2 h</strong> selon la charge. On ne garde que l'<strong>essential bus</strong>, on prévoit un <strong>déroutement</strong> (la QRH donne la durée).</li></ul>"}, {"t": "Le danger des batteries lithium", "kind": "info", "html": "<ul>\n<li><strong>Menace principale</strong> : l'<strong>emballement thermique</strong> → feu, dégazage, explosion.</li>\n<li><strong>Facteurs</strong> : le <strong>nombre</strong> de batteries (avion + appareils des passagers), la <strong>température</strong>, l'<strong>état physique</strong> (choc, perforation, écrasement → court-circuit interne), la <strong>charge</strong> (surcharge, charge rapide, chargeur défectueux).</li>\n<li><strong>Propagation</strong> : un élément surchauffe et déclenche ses voisins.</li>\n<li><strong>Confinement</strong> : boîtier en acier inoxydable ou titane, isolation thermique (sacs, boîtes anti-feu), évacuation des gaz vers l'extérieur, parfois un extincteur.</li>\n<li><strong>En vol</strong> : impossible de <strong>larguer</strong> la batterie, fumées toxiques en cabine, accès difficile, dommages possibles à la structure pressurisée.</li></ul>"}, {"t": "Produire du continu", "kind": "info", "html": "<ul>\n<li><strong>Vocabulaire</strong> : <strong>génératrice DC</strong> (sort du continu) ; <strong>alternateur DC</strong> (produit de l'alternatif redressé en interne par diodes) ; <strong>génératrice AC</strong> ; <strong>démarreur-génératrice</strong> ; alternateur à aimant permanent (auto-excité).</li>\n<li><strong>Génératrice</strong> : une bobine tourne dans un champ → une tension <strong>alternative</strong> est induite (Faraday) → le <strong>collecteur + balais</strong> la redresse mécaniquement → continu <strong>pulsé</strong>. L'alternateur DC redresse par <strong>diodes</strong> : plus lisse.</li>\n<li><strong>Régulateur de tension</strong> : la tension varie avec le régime et la charge ; il agit sur le <strong>courant d'excitation</strong> (inducteur). Plus d'excitation = champ plus fort = tension plus haute. Bus tenu entre <strong>26 et 30 V</strong> (28 V nominal).</li>\n<li><strong>Protection contre le courant inverse</strong> (diode ou relais) : sans elle, quand la génératrice ne produit plus, la batterie se vide dedans et la fait <strong>tourner en moteur</strong>. Obligatoire.</li>\n<li><strong>Démarreur-génératrice</strong> : moteur au démarrage (500 à 1 500 A), génératrice ensuite. Gain de masse ; petits jets, turbopropulseurs, APU.</li></ul>"}, {"t": "Produire de l'alternatif", "kind": "info", "html": "<ul>\n<li><strong>Alternateur triphasé sans balais</strong> (standard) : une petite <strong>excitatrice</strong> sur le même arbre produit de l'alternatif, redressé par des <strong>diodes tournantes</strong>, qui alimente l'inducteur du rotor ; le <strong>stator fixe</strong> sort 3 phases à 120° : <strong>115/200 V 400 Hz</strong>. Pas de balais : fiable, pas d'usure, pas d'étincelle.</li>\n<li>La <strong>GCU</strong> règle la tension par le courant d'excitation.</li>\n<li><strong>f (Hz) = tr/min × nombre de pôles / 120</strong>. Exemples : 4 pôles à 12 000 tr/min = 400 Hz ; 12 pôles à 4 000 tr/min = 400 Hz. Donc, pour un 400 Hz fixe, l'alternateur doit tourner à <strong>vitesse constante</strong>.</li>\n<li><strong>Fréquence sauvage</strong> (frequency wild, ATR 72) : entraîné directement, sans CSD → 300 à 800 Hz. Simple et léger ; bon pour le dégivrage, le chauffage, les petits moteurs ; <strong>pas pour les calculateurs</strong>.</li>\n<li><strong>Entraînement</strong> : moteur (direct ou par CSD/IDG), APU, <strong>RAT</strong> (ultime secours), moteur hydraulique (rare).</li></ul>"}, {"t": "CSD, IDG et convertisseurs", "kind": "info", "html": "<ul>\n<li><strong>CSD</strong> (entraînement à vitesse constante, hydromécanique : pompe et moteur variables) : régime moteur variable en entrée, vitesse <strong>fixe</strong> en sortie (400 Hz).</li>\n<li><strong>IDG = CSD + alternateur</strong> en un seul bloc, plus léger et compact. Standard sur les gros avions.</li>\n<li><strong>Surveillé</strong> : température et pression d'huile, niveau, vitesse de sortie (fréquence), état de désaccouplement. <strong>Désaccouplement automatique</strong> si surchauffe ou pression basse.</li>\n<li><strong>Désaccouplement en vol = définitif</strong> : réaccouplement <strong>au sol</strong> seulement. Le bus passe sur une autre source.</li>\n<li><strong>Circuit d'huile propre</strong>, séparé du moteur : une fuite d'IDG peut <strong>ressembler à une fuite d'huile moteur</strong>.</li>\n<li><strong>Transformateur</strong> : change la <strong>tension</strong> alternative <strong>sans changer la fréquence</strong> (induction mutuelle, sans pièce mobile) : 200 V → 115 V ou 26 V.</li>\n<li><strong>TRU</strong> (transfo-redresseur) : 115/200 V AC → <strong>28 V DC</strong>. Principale source de continu, 2 ou 3 en parallèle.</li>\n<li><strong>Onduleur statique</strong> : 28 V DC → <strong>115 V AC</strong> monophasé 400 Hz, en <strong>secours</strong>.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Ni-Cd : <strong>1,2 V</strong> par élément, <strong>24</strong> éléments pour 28 V.</li>\n<li>Série = <strong>tension</strong> ; parallèle = <strong>capacité</strong>.</li>\n<li><strong>TRU</strong> : AC → DC. <strong>Onduleur</strong> : DC → AC.</li>\n<li>Le transformateur change la tension, <strong>pas la fréquence</strong>.</li>\n<li>IDG déconnecté en vol : <strong>on ne le récupère pas</strong> avant le sol.</li>\n<li>La fréquence dépend du <strong>régime</strong> : sans CSD, elle varie (frequency wild).</li></ul>"}], "oral": ["Quels sont les rôles de la batterie de bord ? Cite les types utilisés.", "Combien d'éléments Ni-Cd faut-il pour 28 V ? Pourquoi la tension de charge est-elle plus élevée ?", "Définis la capacité. Quel est l'effet de la température ? Quelle autonomie reste-t-il sur batterie seule ?", "Quels sont les risques des batteries lithium et comment contient-on un emballement thermique ?", "Explique le fonctionnement d'une génératrice continue, du régulateur de tension et de la protection contre le courant inverse.", "Décris l'alternateur triphasé sans balais. Donne la relation entre fréquence, régime et nombre de pôles.", "Rôle du CSD et de l'IDG ? Que se passe-t-il après un désaccouplement en vol ?", "Rôle du transformateur, du TRU et de l'onduleur statique."]}, "distribution": {"cards": [{"t": "Les barres (bus)", "kind": "info", "html": "<ul>\n<li><strong>Barre</strong> (busbar) : le point central du réseau. Elle <strong>reçoit</strong> le courant de toutes les sources (génératrices, batteries, groupe de parc) et le <strong>distribue</strong> aux consommateurs à travers leurs disjoncteurs. Elle permet de coupler des sources et de basculer automatiquement.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Bus</th>\n<th>Alimentation</th>\n<th>Usage</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>AC</strong></td>\n<td>115/200 V 400 Hz triphasé</td>\n<td>Fortes charges</td></tr>\n<tr>\n<td><strong>DC</strong></td>\n<td>28 V</td>\n<td>Avionique, éclairage, commandes</td></tr>\n<tr>\n<td><strong>Essential</strong></td>\n<td>Sources normales + secours</td>\n<td>Systèmes essentiels</td></tr>\n<tr>\n<td><strong>Emergency</strong></td>\n<td>Batterie ou RAT</td>\n<td>Instruments vitaux</td></tr>\n<tr>\n<td><strong>Battery bus</strong></td>\n<td>Directement la batterie, toujours sous tension</td>\n<td>—</td></tr>\n<tr>\n<td><strong>Hot / ground bus</strong></td>\n<td>Toujours relié à la batterie, utilisé au sol</td>\n<td>Entretien, servicing</td></tr></tbody></table>\n<p>Les bus sont séparés pour la redondance et les priorités.</p>"}, {"t": "Masse commune et sources", "kind": "info", "html": "<ul>\n<li><strong>La structure sert de masse commune</strong> (retour du courant) : moins de fils, donc moins de masse.</li>\n<li>Conséquence : <strong>la métallisation est vitale</strong>. Toutes les pièces au même potentiel, tresses aux jonctions (aile-fuselage). Mauvaise métallisation = parasites, corrosion, fausses alarmes.</li>\n<li><strong>Groupe de parc</strong> : 115/200 V 400 Hz ou 28 V DC, au sol, moteurs et APU arrêtés.</li>\n<li><strong>Priorité des sources</strong> : <strong>au sol</strong> : parc &gt; APU &gt; génératrices moteur ; <strong>en vol</strong> : génératrices moteur &gt; APU &gt; RAT &gt; batterie. Le transfert est automatique et évite de coupler des sources différentes.</li></ul>"}, {"t": "Partage, délestage, pannes", "kind": "info", "html": "<ul>\n<li><strong>Partage de charge</strong> (load sharing) : plusieurs génératrices se partagent la charge à parts égales, via les GCU.</li>\n<li><strong>Délestage</strong> (load shedding) : on coupe automatiquement ou à la main les <strong>non-essentiels</strong> quand la puissance manque (offices, divertissement) pour garder l'essential bus.</li>\n<li><strong>Panne de source</strong> (génératrice, TRU, APU) : la source est perdue, on <strong>transfère</strong> vers une autre (bus tie), avec parfois du délestage. <strong>Récupérable.</strong></li>\n<li><strong>Panne de barre</strong> (court-circuit sur la barre, disjoncteur ouvert) : <strong>tous les consommateurs de cette barre</strong> sont perdus, la barre est isolée (BUS FAULT). <strong>Plus grave.</strong></li></ul>"}, {"t": "Les réseaux continus", "kind": "info", "html": "<ul>\n<li><strong>Monomoteur CS-23</strong> : batterie (par un relais) et alternateur (par son régulateur) sur une ou deux barres. Perte de l'alternateur → <strong>batterie seule, temps limité</strong>. Certains, comme le SR20, ont 2 batteries, 2 alternateurs et plusieurs barres.</li>\n<li><strong>Bimoteur CS-23</strong> (exemple DA42) : une génératrice et une barre par moteur ; un <strong>bus tie</strong> les relie si besoin ; batterie + barre de secours. Une génératrice en panne → l'autre alimente les deux côtés. Les deux en panne → batterie seule.</li>\n<li><strong>CS-25</strong> : le continu vient des <strong>TRU</strong> branchés sur l'alternatif ; barres DC gauche et droite + essential + emergency ; batterie + onduleur statique pour l'alternatif de secours. Un TRU en panne → les autres prennent le relais.</li>\n<li><strong>Consommateurs DC</strong> : avionique, navigation, calculateurs de commandes de vol, détection feu, éclairage, pompes de secours, anti-skid, réchauffage des sondes, vannes carburant et hydrauliques, charge batterie. Les systèmes critiques sont souvent alimentés en AC <strong>et</strong> en DC.</li></ul>"}, {"t": "Les réseaux alternatifs", "kind": "info", "html": "<ul>\n<li><strong>Séparé</strong> (split) : côtés gauche et droit indépendants, ils peuvent être déphasés. Simple, pas de synchronisation, mais <strong>pas de secours automatique</strong> si un côté tombe.</li>\n<li><strong>Parallèle</strong> : les génératrices sont couplées sur une barre commune. Partage de charge, transfert automatique, mais il faut <strong>synchroniser</strong> et protéger. C'est le standard CS-25.</li>\n<li><strong>Transferts</strong> : au démarrage, l'APU puis les génératrices moteur prennent le relais. Une génératrice en panne → le bus tie se ferme, l'autre alimente tout. Perte de tout l'AC normal → <strong>RAT</strong> + essential AC + onduleur. Transfert en moins de 50 ms.</li>\n<li><strong>Conditions de couplage</strong> (vérifiées par la GCU) : <strong>tension égale</strong> (à quelques % près), <strong>fréquence égale</strong> (±0,1 Hz), <strong>même ordre des phases</strong>, <strong>déphasage proche de zéro</strong> (&lt; 10 à 20°). Sinon, courants de circulation énormes.</li>\n<li><strong>Puissance apparente</strong> en <strong>VA</strong> : VA = U × I (monophasé) ou √3 × U × I (triphasé). Les génératrices sont données en <strong>kVA</strong> (ex. 90 kVA). Puissance réelle (W) = VA × facteur de puissance.</li>\n<li><strong>Consommateurs AC</strong> : pompes (carburant, hydrauliques), ventilateurs, feux extérieurs, pare-brise chauffant.</li></ul>"}, {"t": "Les moteurs électriques", "kind": "info", "html": "<ul>\n<li><strong>Rôle</strong> : transformer l'énergie électrique en <strong>énergie mécanique</strong> (rotation ou mouvement linéaire) : pompes carburant et hydrauliques, ventilateurs, vérins (trims, parfois volets), démarreur. C'est la fonction inverse de la génératrice.</li>\n<li><strong>Même construction</strong> (rotor + stator + champs) : un courant dans les bobines fait tourner (moteur) ; faire tourner les bobines dans un champ produit du courant (génératrice). D'où le <strong>démarreur-génératrice</strong>.</li>\n<li><strong>Couple</strong> : interaction entre le champ du stator (fixe) et celui du rotor ; il augmente avec la <strong>tension</strong> et le <strong>courant</strong>.</li>\n<li><strong>Démarrage</strong> : petits moteurs (CS-23) = la batterie suffit, mais <strong>2 à 3 essais</strong> max (batterie vide, démarreur qui chauffe) ; gros réacteurs (CS-25) = couple énorme, <strong>batterie insuffisante</strong> : il faut un <strong>groupe de parc ou l'APU</strong>.</li>\n<li><strong>Rotor bloqué</strong> (roulement grippé, corps étranger) : le moteur reste alimenté, courant <strong>5 à 10 fois</strong> le normal → bobinages qui chauffent, isolant qui fond, court-circuit, <strong>feu</strong>. Le disjoncteur doit sauter vite.</li>\n<li><strong>Emballement</strong> (perte de la charge sur l'arbre) : le moteur accélère sans contrôle → survitesse, roulements et arbre cassés, rotor qui se désintègre. Le <strong>courant et le couple baissent</strong>.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Priorité <strong>au sol</strong> : parc d'abord ; <strong>en vol</strong> : génératrices moteur d'abord.</li>\n<li>Panne de <strong>barre</strong> = plus grave qu'une panne de <strong>source</strong>.</li>\n<li>Couplage : tension, fréquence, <strong>ordre des phases</strong> et <strong>phase</strong> identiques.</li>\n<li>Puissance des génératrices en <strong>kVA</strong>, pas en kW.</li>\n<li>Rotor bloqué = courant <strong>très élevé</strong> ; emballement = courant <strong>en baisse</strong>.</li>\n<li>Gros réacteur : la batterie seule <strong>ne suffit pas</strong> à le démarrer.</li></ul>"}], "oral": ["Qu'est-ce qu'une barre ? Cite les différents types de bus.", "Pourquoi la structure sert-elle de masse commune, et quelle conséquence pour la métallisation ?", "Donne l'ordre de priorité des sources au sol et en vol.", "Différencie partage de charge et délestage, panne de source et panne de barre.", "Décris le réseau continu d'un monomoteur, d'un bimoteur CS-23 et d'un avion CS-25.", "Compare les réseaux alternatifs séparé et parallèle. Quelles conditions faut-il pour coupler deux alternateurs ?", "Que se passe-t-il si le rotor d'un moteur électrique se bloque ? Et s'il s'emballe ?"]}, "quatretemps": {"cards": [{"t": "Les grandeurs du moteur", "kind": "info", "html": "<ul>\n<li><strong>Régime</strong> (tr/min) : nombre de tours du vilebrequin par minute. Trait rouge = maximum ; arc vert = utilisation continue ; arcs jaune ou rouge = temps limité. Le régime seul <strong>ne dit pas</strong> la puissance.</li>\n<li><strong>Couple</strong> (N·m ou lb·ft) : la force de rotation sur le vilebrequin. Un gros couple permet d'accélérer ou de porter une charge à bas régime ; il est maximal à régime moyen. Il peut limiter le réducteur d'hélice.</li>\n<li><strong>Puissance = couple × régime</strong> (ch ou kW). Le pic de puissance arrive à un régime <strong>plus haut</strong> que le pic de couple. Elle dépend aussi de la MAP, de l'air, de l'âge du moteur.</li></ul>"}, {"t": "La pression d'admission (MAP)", "kind": "info", "html": "<ul>\n<li><strong>MAP</strong> = pression <strong>absolue</strong> dans le collecteur d'admission, <strong>après le papillon</strong>. Unité : pouces de mercure (inHg) ou hPa.</li>\n<li><strong>Faible MAP</strong> = faible puissance (ralenti, descente). <strong>Forte MAP</strong> = pleine puissance (décollage, montée). On règle la puissance avec la MAP sur un moteur non suralimenté.</li>\n<li><strong>Moteur arrêté</strong>, la MAP indique la <strong>pression ambiante</strong> (~30 inHg au niveau de la mer).</li>\n<li><strong>Moteur atmosphérique</strong> : on perd <strong>environ 1 inHg par 1 000 ft</strong> à manette fixe, car l'air se raréfie.</li>\n<li><strong>MAP + régime = puissance réelle</strong>.</li></ul>"}, {"t": "Consommation et volumes", "kind": "info", "html": "<ul>\n<li><strong>Consommation spécifique</strong> (SFC) : le carburant consommé par unité de puissance et par heure (lb/ch/h ou kg/kW/h). Plus elle est basse, plus le moteur est efficace. Essence 0,45 à 0,55 lb/ch/h ; diesel 0,35 à 0,45. Elle est <strong>meilleure vers 65 à 75 %</strong> de puissance.</li>\n<li><strong>Cylindrée</strong> (volume balayé) : volume parcouru par le piston du PMB au PMH.</li>\n<li><strong>Volume mort</strong> : ce qui reste dans la chambre au PMH.</li>\n<li><strong>Volume total</strong> = cylindrée + volume mort.</li>\n<li><strong>Taux de compression = volume total / volume mort</strong>. Essence 7:1 à 11:1 ; diesel 14:1 à 22:1. Plus il est élevé, <strong>meilleur est le rendement thermique</strong>.</li></ul>\n<p><strong>Exemple</strong> : cylindrée 900 cm³, volume mort 100 cm³ → volume total 1 000 cm³ → taux = 1 000 / 100 = <strong>10:1</strong>.</p>"}, {"t": "Le cycle à 4 temps", "kind": "info", "html": "<p>Le moteur transforme l'énergie chimique (air + carburant) en chaleur, puis en rotation du vilebrequin. Un cycle = 4 courses du piston = <strong>2 tours de vilebrequin (720°)</strong>. Combustion <strong>intermittente</strong>, à <strong>volume constant</strong> ; rendement thermique ≈ <strong>30 %</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>Temps</th>\n<th>Piston</th>\n<th>Soupapes</th>\n<th>Vilebrequin</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>1. Admission</strong></td>\n<td>PMH → PMB</td>\n<td>Admission <strong>ouverte</strong></td>\n<td>0 → 180°</td></tr>\n<tr>\n<td><strong>2. Compression</strong></td>\n<td>PMB → PMH</td>\n<td><strong>Les deux fermées</strong></td>\n<td>180 → 360°</td></tr>\n<tr>\n<td><strong>3. Combustion-détente</strong></td>\n<td>PMH → PMB</td>\n<td>Fermées ; étincelle près du PMH</td>\n<td>360 → 540° : <strong>le seul temps moteur</strong></td></tr>\n<tr>\n<td><strong>4. Échappement</strong></td>\n<td>PMB → PMH</td>\n<td>Échappement <strong>ouverte</strong></td>\n<td>540 → 720°</td></tr></tbody></table>\n<p>À l'admission, la pression dans le cylindre est <strong>inférieure</strong> à la pression atmosphérique : le mélange est aspiré.</p>"}, {"t": "Les pièces du moteur", "kind": "info", "html": "<ul>\n<li><strong>Carter</strong> : le bâti, qui porte le vilebrequin.</li>\n<li><strong>Vilebrequin</strong> : transforme le mouvement <strong>linéaire</strong> des pistons en <strong>rotation</strong>.</li>\n<li><strong>Bielle</strong> : relie le piston au vilebrequin. <strong>Axe de piston</strong> : relie le piston à la bielle.</li>\n<li><strong>Piston</strong> : comprime le mélange et transmet la force. <strong>Segments</strong> : assurent l'<strong>étanchéité</strong> de la chambre et <strong>contrôlent l'huile</strong>.</li>\n<li><strong>Cylindre</strong> : le tube où coulisse le piston. <strong>Culasse</strong> : contient la chambre de combustion et les soupapes.</li>\n<li><strong>Soupapes</strong> d'admission et d'échappement ; <strong>ressorts</strong> qui les referment.</li>\n<li><strong>Arbre à cames</strong> : commande l'ouverture des soupapes ; il tourne <strong>à la moitié du régime</strong> du vilebrequin (entraîné par pignon, chaîne ou courroie).</li>\n<li><strong>Tiges de culbuteurs</strong> (transmettent le mouvement de la came) et <strong>culbuteurs</strong> (pivotent pour ouvrir la soupape).</li>\n<li><strong>Paliers</strong> : réduisent le frottement.</li></ul>"}, {"t": "Les architectures", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Avantages</th>\n<th>Inconvénients</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>À plat</strong> (boxer : Lycoming O-320, IO-360, IO-540 ; Continental IO-550), le plus courant</td>\n<td>Très bien équilibré (peu de vibrations), <strong>CG bas</strong>, peu haut, cylindres bien refroidis</td>\n<td>Large ; cylindres arrière moins accessibles ; long vilebrequin sur les gros modèles</td></tr>\n<tr>\n<td><strong>En ligne</strong></td>\n<td>Simple, petite surface frontale, accessible</td>\n<td>CG haut (ou graissage complexe s'il est inversé), plus de vibrations, très long au-delà de 5 à 6 cylindres</td></tr>\n<tr>\n<td><strong>En étoile</strong></td>\n<td>Très bien refroidi (tout dans le souffle de l'hélice), gros couple à bas régime, court</td>\n<td>Diamètre énorme (traînée), distribution complexe, vibrations ; presque disparu</td></tr></tbody></table>"}, {"t": "Deux temps et diesel", "kind": "info", "html": "<ul>\n<li><strong>Deux temps</strong> : 1 tour (360°) = 1 temps moteur. Meilleur rapport puissance/masse, simple (pas de soupapes ni d'arbre à cames), léger, pas cher. Mais consomme beaucoup, pollue (carburant et huile imbrûlés), <strong>huile mélangée à l'essence</strong> (graissage perdu). ULM, paramoteurs.</li>\n<li><strong>Diesel</strong> (Austro AE300, Continental CD-155) : allumage <strong>par compression</strong>, au <strong>Jet A-1</strong>. Démarrage à froid avec des <strong>bougies de préchauffage</strong>. <strong>Pas de givrage carburateur</strong> (injection directe). Souvent <strong>turbocompressé</strong>. Moins puissant qu'un moteur essence de même cylindrée.</li>\n<li><strong>Émissions</strong> : essence = surtout CO et hydrocarbures ; diesel = surtout suies et NOx.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>2 tours</strong> de vilebrequin par cycle, pas 4.</li>\n<li>Pendant la <strong>compression</strong>, les <strong>deux</strong> soupapes sont fermées.</li>\n<li>L'arbre à cames tourne <strong>deux fois moins vite</strong> que le vilebrequin.</li>\n<li>Taux de compression = <strong>total / mort</strong>, pas cylindrée / mort.</li>\n<li>Puissance = couple × <strong>régime</strong>.</li>\n<li>Moteur arrêté, la MAP montre la <strong>pression ambiante</strong>, pas zéro.</li></ul>"}], "oral": ["Définis régime, couple, puissance, MAP et consommation spécifique.", "Définis cylindrée, volume mort et taux de compression. Calcule le taux pour une cylindrée de 1 200 cm³ et un volume mort de 150 cm³.", "Décris les quatre temps : position du piston, des soupapes et angle du vilebrequin.", "Cite les pièces principales d'un moteur à pistons et leur rôle.", "Compare les moteurs à plat, en ligne et en étoile.", "Donne les avantages et les inconvénients du moteur deux temps et du diesel d'avion."]}, "carbu": {"cards": [{"t": "Carburants et indice d'octane", "kind": "info", "html": "<ul>\n<li><strong>AVGAS 100LL</strong> (bleue) : pour les moteurs à <strong>allumage commandé</strong>. Autres grades : UL91 et UL94 sans plomb, G100UL qui remplace le 100LL.</li>\n<li><strong>Jet A-1</strong> : le <strong>seul</strong> carburant approuvé pour les <strong>diesels d'avion</strong> certifiés. Incolore, sans plomb, pas d'indice d'octane. Congélation ≤ −47 °C, point éclair ≥ 38 °C, densité 0,775 à 0,84 kg/L.</li>\n<li><strong>Indice d'octane</strong> : la résistance du carburant à la <strong>détonation</strong>. On le mesure par comparaison avec un mélange d'iso-octane (100) et d'heptane (0). Plus il est haut, plus on peut <strong>comprimer</strong> sans détonation. 100LL ≈ 100.</li></ul>"}, {"t": "La détonation", "kind": "info", "html": "<ul>\n<li><strong>C'est quoi</strong> : une partie du mélange <strong>explose</strong> d'un coup, <strong>avant l'arrivée du front de flamme</strong> normal (après l'étincelle).</li>\n<li><strong>Causes</strong> : taux de compression élevé, <strong>MAP élevée</strong>, cylindres trop chauds (CHT), avance à l'allumage trop grande, carburant à indice d'octane trop bas, <strong>mélange pauvre</strong>, forte puissance + air d'admission chaud.</li>\n<li><strong>Effets</strong> : ondes de choc (piston et gorges de segments abîmés), surchauffe (soupapes et pistons brûlés), perte de puissance, vibrations, piston percé.</li>\n<li><strong>Signes</strong> : cliquetis (difficile à entendre au casque), moteur rugueux, perte de puissance, <strong>CHT et température d'huile qui montent</strong>, régime qui peut baisser, EGT qui monte puis baisse.</li>\n<li><strong>Que faire</strong> : <strong>réduire la puissance</strong>, <strong>enrichir</strong>, réduire le régime, <strong>prendre de la vitesse</strong> pour refroidir.</li>\n<li><strong>Diesel</strong> : la combustion par compression est normale ; un « cognement » vient d'un mauvais calage d'injection ou d'injecteurs usés.</li></ul>"}, {"t": "L'auto-allumage (pré-allumage)", "kind": "info", "html": "<ul>\n<li><strong>C'est quoi</strong> : la combustion démarre <strong>avant l'étincelle</strong>, à cause d'un <strong>point chaud</strong> dans la chambre. Elle pousse contre le piston qui <strong>remonte</strong>.</li>\n<li><strong>Causes</strong> : bougie surchauffée, <strong>calamine</strong> (dépôts qui rougissent), soupape d'échappement ou tête de piston trop chaude, mélange pauvre, CHT élevée.</li>\n<li><strong>Effets</strong> : pression énorme, bielles tordues, pistons et soupapes fondus. <strong>Plus destructeur que la détonation.</strong></li>\n<li><strong>Diesel</strong> : rare (c'est l'injection qui décide du moment), sauf injecteur défectueux.</li></ul>"}, {"t": "Eau, densité, vapour lock", "kind": "info", "html": "<ul>\n<li><strong>Contrôle d'eau</strong> : on purge les puisards (ailes, nourrice) avec un godet. <strong>L'eau, plus lourde, est au fond</strong> ; elle forme des gouttes ou un dépôt trouble. Eau incolore, AVGAS bleue, Jet A-1 incolore.</li>\n<li><strong>Quand purger</strong> : avant le premier vol du jour, après un avitaillement (surtout d'origine inconnue), après un long stockage ou de la pluie, si les réservoirs sont restés à moitié vides (condensation).</li>\n<li><strong>Densité</strong> : AVGAS 0,68 à 0,72 kg/L ; Jet A-1 0,775 à 0,84 kg/L. Elle sert à passer des litres aux kilos (masse et centrage, autonomie). Le carburant se dilate à la chaleur.</li>\n<li><strong>Volatilité</strong> : essence <strong>très volatile</strong> (bonne vaporisation) ; Jet A-1 <strong>peu volatil</strong> (démarrage à froid difficile mais plus sûr). <strong>Viscosité</strong> : Jet A-1 plus visqueux (bon filtrage, réchauffage au froid).</li>\n<li><strong>Vapour lock</strong> (essence seulement) : le carburant se vaporise dans les tuyaux, des bulles privent le moteur de carburant. Causes : carburant chaud + basse pression (altitude, jour chaud, faible débit). Parades : <strong>pompe de gavage</strong>, tuyaux isolés, recirculation.</li></ul>"}, {"t": "Les pompes à carburant", "kind": "info", "html": "<ul>\n<li><strong>Pompe mécanique entraînée par le moteur</strong> : elle fournit une pression continue au carburateur ou à l'injection (3 à 30 psi). Elle marche <strong>tant que le moteur tourne</strong>, <strong>sans électricité</strong>.</li>\n<li>La <strong>pompe électrique</strong> (boost) seule ne donne que 2 à 10 psi : parfois insuffisant à pleine puissance.</li>\n<li><strong>Pompe électrique ON</strong> : au <strong>décollage</strong> et à l'<strong>atterrissage</strong> (si la pompe moteur lâche, le moteur continue), en <strong>urgence</strong>, contre le <strong>vapour lock</strong>.</li></ul>"}, {"t": "Le carburateur", "kind": "info", "html": "<ul>\n<li><strong>Rôle</strong> : doser l'air et le carburant dans le bon rapport, avec une compensation automatique selon la puissance, l'altitude et la température, et un réglage par le pilote (mixture).</li>\n<li><strong>Rapports air/carburant</strong> : <strong>puissance max 12,6:1</strong> ; <strong>stœchiométrique 14,7:1</strong> ; <strong>économie max 15,4:1</strong>.</li>\n<li><strong>Carburateur à cuve</strong> :<ol>\n<li>niveau constant dans la cuve (<strong>flotteur + pointeau</strong>) ;</li>\n<li>le carburant passe par le <strong>gicleur</strong> principal jusqu'au <strong>venturi</strong> ;</li>\n<li>l'air accélère dans le venturi → la pression baisse (<strong>Bernoulli</strong>) ;</li>\n<li>la dépression aspire le carburant, qui est pulvérisé ;</li>\n<li>le mélange passe le <strong>papillon</strong> puis va aux cylindres.</li></ol></li>\n<li><strong>Circuit de ralenti</strong> : papillon fermé, la dépression du venturi ne suffit plus, un passage spécial alimente le moteur.</li>\n<li><strong>Tube d'émulsion</strong> (air bleed) : de l'air entre par des trous et émulsionne le carburant → débit régulier sur toute la plage.</li>\n<li><strong>Altitude</strong> : l'air est moins dense, mais le carburateur est réglé pour le niveau de la mer → le mélange <strong>s'enrichit</strong> → le pilote <strong>appauvrit</strong> (au pic d'EGT, puis un peu plus riche). Rares carburateurs à capsule anévroïde automatique.</li>\n<li><strong>Pompe de reprise</strong> : un jet de carburant quand on ouvre vite les gaz (évite le trou à l'accélération). <strong>Enrichisseur</strong> : plus de carburant à pleine puissance.</li>\n<li><strong>Primer</strong> : pompe à main qui envoie un peu de carburant pur aux cylindres pour le démarrage à froid.</li></ul>"}, {"t": "Le feu de carburateur", "kind": "info", "html": "<ul>\n<li><strong>Causes</strong> : fuite de carburant sous le moteur + échappement chaud + <strong>retour de flamme</strong> au démarrage ; <strong>trop de primer</strong> (carburant liquide dans l'admission).</li>\n<li><strong>Signes</strong> : flammes ou fumée à l'entrée d'air ou à l'échappement, odeur de brûlé.</li>\n<li><strong>Actions</strong> :<ol>\n<li>mélange sur <strong>étouffoir</strong> ;</li>\n<li>robinet carburant <strong>OFF</strong> ;</li>\n<li>magnétos <strong>OFF</strong> ;</li>\n<li>manette des gaz <strong>plein ouvert</strong> (un maximum d'air) ;</li>\n<li><strong>continuer à lancer</strong> le démarreur pour aspirer et souffler le feu.</li></ol></li></ul>"}, {"t": "Le givrage carburateur", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Température</th>\n<th>Où</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Évaporation du carburant</strong> (le plus fréquent)</td>\n<td><strong>+4 à +27 °C</strong> si humidité &gt; 50 % (parfois plus chaud)</td>\n<td>Zone du gicleur</td></tr>\n<tr>\n<td><strong>Givrage du papillon</strong></td>\n<td>0 à +3 °C</td>\n<td>Derrière le papillon presque fermé</td></tr>\n<tr>\n<td><strong>Givrage d'impact</strong></td>\n<td>−10 à 0 °C, humidité visible</td>\n<td>Prises d'air, filtres, papillon</td></tr></tbody></table>\n<ul>\n<li><strong>Causes</strong> : l'<strong>effet venturi</strong> (l'air accélère et se refroidit de 15 à 30 °C) + l'<strong>évaporation</strong> du carburant qui prend de la chaleur.</li>\n<li><strong>Conditions à risque</strong> : <strong>0 à +25 °C</strong>, humidité &gt; 60 %, humidité visible (nuages, brouillard, bruine), <strong>faible puissance</strong> (descente, approche, attente).</li>\n<li><strong>Effets</strong> : moins d'air → perte de puissance progressive, mélange <strong>trop riche</strong>, moteur rugueux, bougies encrassées, arrêt possible.</li>\n<li><strong>Signes</strong> : hélice à <strong>calage fixe</strong> → <strong>le régime baisse</strong> ; hélice à <strong>vitesse constante</strong> → <strong>la MAP baisse</strong> (le régulateur tient le régime). CHT et EGT montent un peu puis baissent.</li></ul>"}, {"t": "Le réchauffage carburateur", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> : de l'air chaud pris autour de l'<strong>échappement</strong> remplace l'air froid.</li>\n<li><strong>Effet</strong> : l'air chaud est moins dense → <strong>mélange plus riche</strong> et <strong>puissance −10 à 20 %</strong>.</li>\n<li><strong>S'il y a du givre</strong> : la puissance <strong>baisse d'abord</strong> (air chaud + eau de fonte), puis <strong>remonte</strong> après 30 s à 2 min, quand la glace a fondu.</li>\n<li><strong>S'il n'y a pas de givre</strong> : la puissance baisse et <strong>reste basse</strong>, sans remontée.</li>\n<li>C'est le test classique : <strong>baisse puis remontée = il y avait du givre</strong>.</li></ul>"}, {"t": "L'injection", "kind": "info", "html": "<ul>\n<li><strong>Différence</strong> : pas de venturi. L'air passe par le papillon, le carburant est injecté dans la tubulure ou le cylindre. <strong>Pas de chute de température, peu ou pas de givrage</strong> (sauf le givrage d'admission : on a un <strong>air alternatif</strong>).</li>\n<li><strong>Avantages</strong> : un injecteur par cylindre, <strong>mélange égal</strong> partout (moteur plus doux, meilleur réglage de la mixture), réponse plus franche (remise de gaz), <strong>fonctionne dans toutes les positions</strong> (voltige : le carburateur à cuve exige un facteur de charge positif), meilleure consommation.</li>\n<li><strong>Inconvénients</strong> : <strong>démarrage à chaud difficile</strong> (vapour lock, il faut parfois noyer le moteur) ; <strong>sans pression de carburant, le moteur s'arrête</strong> (pompe de secours obligatoire ; un carburateur peut marcher par gravité).</li>\n<li><strong>Air alternatif</strong> : une porte qui prend de l'air chaud dans le capot si l'entrée normale est bouchée (givre, filtre colmaté, oiseau). Comme le réchauffage carbu : mélange plus riche, perte de puissance.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>Détonation</strong> = explosion <strong>après</strong> l'étincelle, avant le front de flamme. <strong>Auto-allumage</strong> = combustion <strong>avant</strong> l'étincelle, par un point chaud. L'auto-allumage est le <strong>plus destructeur</strong>.</li>\n<li>Contre la détonation : <strong>enrichir</strong> et réduire la puissance (pas appauvrir).</li>\n<li>Givrage carbu possible jusqu'à <strong>+27 °C</strong>, et même plus : ce n'est pas un problème de froid.</li>\n<li>Hélice à vitesse constante : le givrage se voit sur la <strong>MAP</strong>, pas sur le régime.</li>\n<li>Réchauffage carbu = mélange <strong>plus riche</strong> et moins de puissance.</li>\n<li>Feu de carbu : manette des gaz <strong>ouverte</strong> et on <strong>continue à lancer</strong>.</li></ul>"}], "oral": ["Qu'est-ce que l'indice d'octane ? Pourquoi permet-il un taux de compression plus élevé ?", "Différencie détonation et auto-allumage : causes, effets, signes et actions.", "Pourquoi et quand purge-t-on les réservoirs ? Qu'est-ce que le vapour lock ?", "Pourquoi un moteur a-t-il une pompe entraînée et une pompe électrique ? Quand utilise-t-on la pompe électrique ?", "Décris le fonctionnement d'un carburateur à cuve et ses dispositifs annexes.", "Cite les trois types de givrage carburateur, leurs causes et leurs signes. Que se passe-t-il quand on tire le réchauffage, avec et sans givre ?", "Compare carburateur et injection."]}, "melange": {"cards": [{"t": "Pourquoi refroidir", "kind": "info", "html": "<ul>\n<li><strong>Protéger</strong> les pièces critiques : culasses, pistons, soupapes, sièges d'échappement. Les tolérances mécaniques sont prévues pour une plage de température.</li>\n<li><strong>Éviter la détonation et l'auto-allumage</strong> (chaleur → cliquetis → dégâts).</li>\n<li><strong>Garder l'huile</strong> sous ~120 à 130 °C (au-delà, elle se dégrade et se carbonise).</li>\n<li><strong>Contrôler la CHT</strong> (limites continues typiques 400 à 500 °F).</li>\n<li><strong>Allonger la vie du moteur</strong> : la surchauffe déforme les culasses, brûle les soupapes, fissure les cylindres.</li></ul>"}, {"t": "Refroidissement par air ou par liquide", "kind": "info", "html": "<ul>\n<li><strong>Par air</strong> : grandes <strong>ailettes</strong> sur les cylindres et les culasses ; flux rapide de l'hélice ; <strong>déflecteurs</strong> (baffles) qui guident l'air sur les zones chaudes ; capot étanche avec entrées contrôlées ; <strong>volets de capot</strong> ; sonde CHT sur le cylindre le plus chaud (souvent le n° 3 ou 5).</li>\n<li><strong>Volets de capot</strong> (cowl flaps) :<ul>\n<li><strong>ouverts</strong> au décollage, en montée, par forte chaleur, au sol (forte puissance, faible vitesse) ;</li>\n<li><strong>fermés</strong> en croisière : moins de traînée et de bruit.</li></ul></li>\n<li><strong>Par liquide</strong> : eau + antigel, pompe entraînée par le moteur, radiateur ; un <strong>thermostat</strong> s'ouvre vers <strong>75 à 90 °C</strong> (fermé à froid pour chauffer vite). Température <strong>stable et indépendante de la vitesse</strong>, mais plus lourd, plus complexe, risque de fuite.</li></ul>"}, {"t": "La CHT", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Arc</th>\n<th>Plage typique</th>\n<th>Signification</th></tr></thead>\n<tbody>\n<tr>\n<td>Vert</td>\n<td>150 à 400 °F (65 à 204 °C)</td>\n<td>Normal</td></tr>\n<tr>\n<td>Jaune</td>\n<td>400 à 500 °F (204 à 260 °C)</td>\n<td>Prudence</td></tr>\n<tr>\n<td>Rouge</td>\n<td>~500 à 550 °F (260 à 288 °C)</td>\n<td>Maximum</td></tr></tbody></table>\n<p><strong>CHT trop haute</strong> : réduire la puissance, <strong>enrichir</strong>, ouvrir les volets de capot, prendre de la vitesse.</p>"}, {"t": "L'huile : viscosité et grades", "kind": "info", "html": "<ul>\n<li><strong>Viscosité</strong> = résistance à l'écoulement. Trop épaisse : circule mal, freine, lubrifie tard. Trop fluide : le film casse, métal contre métal, usure. Il faut assez épais pour séparer les pièces, assez fluide pour circuler vite.</li>\n<li><strong>Température</strong> : <strong>chaud = plus fluide</strong>, <strong>froid = plus épais</strong>. Démarrage à froid : lancement dur, huile lente, usure. Moteur très chaud : film fragile, paliers en danger.</li>\n<li><strong>Grades SAE</strong> : monogrades <strong>SAE 40, 50</strong> (plus le chiffre est grand, plus elle est épaisse à 100 °C). Multigrades <strong>15W-50</strong>, 20W-50 : le chiffre + <strong>W</strong> (winter) = comportement <strong>à froid</strong> ; le second = viscosité <strong>à chaud</strong>.</li>\n<li>Toujours l'huile approuvée par le manuel, et <strong>pas de mélange</strong> de grades.</li></ul>"}, {"t": "Le circuit de lubrification", "kind": "info", "html": "<ul>\n<li><strong>6 rôles</strong> : réduire le <strong>frottement</strong>, <strong>refroidir</strong> (pistons, cylindres, paliers), <strong>nettoyer</strong> (calamine, limaille vers le filtre), aider l'<strong>étanchéité</strong> des segments, <strong>protéger</strong> de la corrosion, <strong>amortir</strong> les chocs.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Carter</th>\n<th>Principe</th>\n<th>Usage</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Humide</strong> (wet sump)</td>\n<td>Huile stockée <strong>dans le carter</strong> ; une pompe de pression ; retour par gravité</td>\n<td>Simple et léger ; petits moteurs (voltige avec circuit spécial vol dos)</td></tr>\n<tr>\n<td><strong>Sec</strong> (dry sump)</td>\n<td><strong>Réservoir séparé</strong> ; pompe de pression + <strong>pompes de récupération plus grosses</strong> qui renvoient l'huile au réservoir</td>\n<td>Huile disponible dans <strong>toutes les attitudes</strong> ; gros moteurs, réacteurs</td></tr></tbody></table>\n<ul>\n<li><strong>Réservoir</strong> : <strong>puits chaud</strong> (hot well, au fond : une petite quantité d'huile circule et chauffe vite), <strong>désaérateur</strong> (sépare l'air par centrifugation, évite la mousse), mise à l'air, volume d'expansion.</li>\n<li><strong>Composants</strong> : clapet anti-retour (pas de retour d'huile moteur arrêté) ; pompe de pression + <strong>soupape de sûreté</strong> (60 à 90 psi) ; pompe de récupération ; filtres d'aspiration, <strong>de pression</strong> (principal, avec by-pass au démarrage et s'il se bouche), de retour ; <strong>radiateur d'huile</strong> avec vanne thermostatique (court-circuite le radiateur quand l'huile est froide, vise 80 à 90 °C) ; capteurs de pression et de température.</li></ul>"}, {"t": "Pression, température, quantité", "kind": "info", "html": "<ul>\n<li><strong>Température haute</strong> → huile plus fluide → <strong>pression basse</strong>.</li>\n<li><strong>Quantité basse</strong> → la pompe se désamorce → <strong>pression qui chute</strong> → surchauffe.</li>\n<li><strong>Pression basse</strong> → mauvais refroidissement et graissage → <strong>température qui monte</strong> vite.</li>\n<li><strong>Trop d'huile</strong> → le vilebrequin barbote → <strong>mousse</strong> → pression instable, température haute. <strong>Ne jamais trop remplir.</strong></li>\n<li><strong>Consommation d'huile</strong> augmentée par : huile trop fluide, usure des cylindres et pistons, <strong>segments usés ou collés</strong>, huile chaude, forte puissance. Une hausse brutale = maintenance.</li>\n<li><strong>Niveau</strong> : selon le manuel. Carter sec = parfois faire tourner le moteur avant ; carter humide = attendre un peu après l'arrêt. Le niveau monte quand l'huile est chaude.</li></ul>"}, {"t": "L'allumage par magnéto", "kind": "info", "html": "<ul>\n<li><strong>Magnéto</strong> : générateur haute tension <strong>autonome</strong>, sans batterie, entraîné par le moteur.</li>\n<li><strong>Séquence</strong> :<ol>\n<li>un aimant tourne → champ variable dans la bobine ;</li>\n<li>le <strong>rupteur</strong> ouvre brutalement le circuit <strong>primaire</strong> ;</li>\n<li>le champ s'effondre → <strong>15 à 30 kV</strong> induits dans le <strong>secondaire</strong> (beaucoup de spires) ;</li>\n<li>le <strong>distributeur</strong> envoie la haute tension à la bonne bougie ;</li>\n<li>l'étincelle saute et enflamme le mélange.</li></ol></li>\n<li><strong>Condensateur</strong> : branché sur le rupteur, il évite l'arc et rend l'étincelle plus franche.</li>\n<li><strong>Contacteur</strong> L / R / BOTH / OFF : sur <strong>OFF</strong>, il <strong>met le primaire à la masse</strong>.</li>\n<li><strong>Double allumage</strong> obligatoire : <strong>redondance</strong> + <strong>2 étincelles par cylindre</strong> (combustion plus rapide et complète, plus de puissance, moteur plus doux, meilleur démarrage).</li></ul>"}, {"t": "Aides au démarrage et essai magnétos", "kind": "info", "html": "<ul>\n<li>À bas régime de lancement, la magnéto donne une étincelle faible. Aides :<ul>\n<li><strong>vibreur</strong> (booster coil) : fait des coupures rapides et donne des <strong>étincelles continues</strong>, coupé quand le moteur tourne ;</li>\n<li><strong>accouplement à impulsion</strong> : un ressort retient l'arbre de la magnéto puis le <strong>lâche près du PMH</strong> → étincelle forte, <strong>retardée</strong> ;</li>\n<li>vibreur à rupteur retardé : transforme le continu de la batterie en courant pulsé → gerbe d'étincelles.</li></ul></li>\n<li><strong>Essai magnétos</strong> (vers 1 700 à 2 000 tr/min) : L → noter la chute → BOTH → R → BOTH.<ul>\n<li><strong>Normal</strong> : petite chute de chaque côté, max <strong>125 à 175 tr/min</strong>, écart G/D &lt; 50 à 100 tr/min.</li>\n<li><strong>Grosse chute ou moteur rugueux</strong> : magnéto ou bougie défectueuse.</li>\n<li><strong>Aucune chute</strong> : une magnéto ne fonctionne pas réellement.</li>\n<li>Sur <strong>OFF</strong>, le moteur doit s'arrêter. <strong>S'il ne s'arrête pas = mauvaise mise à la masse : magnéto toujours « chaude », hélice dangereuse.</strong></li></ul></li>\n<li><strong>Diesel</strong> : pas de magnéto, c'est la chaleur de compression qui enflamme le carburant.</li></ul>"}, {"t": "Le mélange", "kind": "info", "html": "<ul>\n<li><strong>Richesse</strong> = masse d'air / masse de carburant.</li></ul>\n<table>\n<thead>\n<tr>\n<th>Mélange</th>\n<th>Rapport</th>\n<th>Par rapport au pic d'EGT</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Puissance max</strong></td>\n<td>12,5 à 13:1</td>\n<td>Côté <strong>riche</strong></td></tr>\n<tr>\n<td><strong>Stœchiométrique</strong></td>\n<td><strong>14,7:1</strong></td>\n<td>Au <strong>pic</strong> d'EGT</td></tr>\n<tr>\n<td><strong>Économie max</strong></td>\n<td>15,5 à 16,5:1</td>\n<td>Côté <strong>pauvre</strong></td></tr></tbody></table>\n<ul>\n<li><strong>EGT</strong> = température des gaz d'échappement. Elle varie avec la richesse : c'est <strong>l'outil pour régler la mixture</strong> (on appauvrit jusqu'au pic, puis on se place côté riche ou pauvre).</li>\n<li><strong>Pauvre</strong> : économie, combustion propre ; mais <strong>CHT plus haute</strong>, risque de <strong>détonation</strong> à forte puissance, moteur rugueux si trop pauvre.</li>\n<li><strong>Riche</strong> : <strong>refroidit</strong> (le carburant en trop absorbe la chaleur), <strong>marge contre la détonation</strong>, moteur doux ; mais consomme plus, encrasse les bougies, plus de CO et d'imbrûlés.</li>\n<li><strong>Consommation spécifique</strong> : haute côté riche, presque minimale au pic, <strong>minimale un peu côté pauvre</strong>, puis elle remonte si c'est trop pauvre (la puissance s'effondre).</li>\n<li><strong>Diesel</strong> : pas de papillon, l'air entre librement ; la puissance se règle <strong>par la quantité injectée</strong> → <strong>pas de commande de mélange</strong>, une seule manette, pas de risque de détonation en appauvrissant.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li><strong>Volets de capot ouverts</strong> au décollage et en montée, fermés en croisière.</li>\n<li>Huile <strong>chaude</strong> → pression <strong>basse</strong>. <strong>Trop d'huile</strong> → mousse.</li>\n<li>Pompes de <strong>récupération</strong> plus grosses que la pompe de pression (l'huile de retour est chargée d'air).</li>\n<li>Essai magnétos : <strong>aucune chute</strong> = problème, pas un bon signe.</li>\n<li>Sur OFF, la magnéto est <strong>mise à la masse</strong> ; fil de masse coupé = moteur qui ne s'arrête pas.</li>\n<li>Le pic d'EGT est au mélange <strong>stœchiométrique</strong> ; la puissance max est <strong>côté riche</strong>.</li></ul>"}], "oral": ["Pourquoi refroidit-on un moteur à pistons ? Compare refroidissement par air et par liquide.", "Comment utilise-t-on les volets de capot ? Que faire si la CHT est trop haute ?", "Qu'est-ce que la viscosité ? Explique la signification d'une huile 15W-50.", "Cite les six rôles de l'huile. Compare carter humide et carter sec.", "Explique les liens entre pression, température et quantité d'huile.", "Décris le fonctionnement d'une magnéto. Pourquoi deux magnétos ?", "Décris l'essai magnétos et l'interprétation des résultats.", "Définis les mélanges de puissance max, stœchiométrique et d'économie max. Comment utilise-t-on l'EGT ?"]}, "helice": {"cards": [{"t": "Les définitions", "kind": "info", "html": "<ul>\n<li><strong>Hélice</strong> : transforme la puissance (le couple) du moteur en traction.</li>\n<li><strong>Calage fixe</strong> : angle des pales fixe (simple, léger). <strong>Pas variable</strong> : angle réglable en vol.</li>\n<li><strong>Vitesse constante</strong> : l'angle s'ajuste <strong>tout seul</strong> pour garder le <strong>régime choisi</strong>.</li>\n<li><strong>Drapeau</strong> : pales tournées vers ~90°, de profil : <strong>traînée minimale</strong> après une panne moteur.</li>\n<li><strong>Reverse</strong> : au-delà, angle <strong>négatif</strong> → traction vers l'arrière (freinage).</li>\n<li><strong>Pas géométrique</strong> : avance théorique par tour, sans glissement. <strong>Recul</strong> (slip) : écart entre pas géométrique et pas effectif.</li></ul>"}, {"t": "Le régulateur (governor)", "kind": "info", "html": "<ul>\n<li>Un <strong>régulateur à masselottes</strong> (centrifuge) dose l'huile envoyée au moyeu.</li>\n<li><strong>Régime trop haut</strong> → les masselottes s'écartent → <strong>plus de pression d'huile</strong> → <strong>grand pas</strong> → plus de charge → le régime <strong>baisse</strong>.</li>\n<li><strong>Régime trop bas</strong> → moins de pression d'huile → la force centrifuge des pales ramène au <strong>petit pas</strong> → moins de charge → le régime <strong>remonte</strong>.</li>\n<li><strong>Simple effet</strong> : l'huile sert à <strong>diminuer</strong> le pas ; sans huile, le moment de torsion centrifuge pousse les pales vers le <strong>grand pas</strong>. Simple et léger (avions légers).</li>\n<li><strong>Double effet</strong> : l'huile agit <strong>dans les deux sens</strong> ; plus de pression, moyeu complexe, réponse plus rapide, plus de contrôle (gros avions, multimoteurs).</li></ul>"}, {"t": "Manettes et instruments", "kind": "info", "html": "<ul>\n<li>Avec une hélice à vitesse constante : <strong>la manette d'hélice règle le régime</strong>, <strong>la manette des gaz règle la puissance (MAP)</strong>. Sans <strong>manomètre de pression d'admission</strong>, impossible de régler la puissance (le régime seul ne suffit plus).</li>\n<li><strong>Couplemètre</strong> : mesure le couple transmis à l'hélice (en % ou N·m). Surtout sur les moteurs à réducteur et les turbopropulseurs. Il donne la <strong>puissance réelle</strong> et protège du <strong>surcouple</strong> (trait rouge).</li>\n<li><strong>Butée de petit pas / verrou centrifuge</strong> : bloque les pales au <strong>petit pas</strong> à bas régime (arrêt, mise en drapeau) pour éviter traînée et survitesse au démarrage ; il se libère à haut régime.</li>\n<li><strong>Synchronisation</strong> : toutes les hélices au <strong>même régime</strong> → moins de battements (vibrations, bruit). <strong>Synchrophasage</strong> : en plus, un <strong>décalage angulaire</strong> fixe entre les pales → encore moins de vibrations et de bruit en cabine.</li></ul>"}, {"t": "Drapeau, reverse, réducteur", "kind": "info", "html": "<ul>\n<li><strong>Mise en drapeau automatique</strong> : un capteur de <strong>couple négatif</strong> ou de <strong>chute de pression d'huile</strong> détecte la panne → une pompe ou un accumulateur envoie de l'huile haute pression → pales en drapeau.</li>\n<li><strong>Mise en drapeau manuelle</strong> : manette d'hélice <strong>tout en arrière au-delà du cran</strong> + carburant coupé + allumage coupé.</li>\n<li><strong>Sortie du drapeau</strong> : manette en avant, pression d'huile (accumulateur, pompe dédiée) + force centrifuge, aidée par le moulinet ou le démarreur. 10 à 60 s.</li>\n<li><strong>Reverse (plage bêta)</strong> : pales à −10 à −20°, manette sous le ralenti sol ou manette dédiée. Un <strong>contacteur train</strong> l'interdit en vol (certains avions utilisent une partie de la plage bêta en vol comme aérofrein).</li>\n<li><strong>Réducteur</strong> : un moteur rapide donne plus de puissance, mais l'hélice est efficace vers <strong>2 000 à 2 700 tr/min</strong> ; plus vite, les <strong>bouts de pales deviennent supersoniques</strong> (rendement en chute, bruit). Rapports 0,55 à 0,75. Régime hélice = régime moteur × rapport. Exemple du cours : 5 500 tr/min × 0,5 ≈ 2 750 tr/min.</li></ul>"}, {"t": "Utiliser l'hélice", "kind": "info", "html": "<ul>\n<li><strong>Cyclage après le démarrage</strong> : manette plein avant (grand régime), puis lentement tout en arrière (le régime baisse, la <strong>pression d'huile monte</strong>), puis plein avant. Il <strong>purge l'air du moyeu</strong> et vérifie le régulateur.</li>\n<li><strong>Basse vitesse</strong> (décollage, montée) : manette plein avant → <strong>petit pas</strong>, régime haut → traction max.</li>\n<li><strong>La vitesse augmente</strong> : le régulateur <strong>augmente le pas</strong> tout seul ; le <strong>régime reste constant</strong>.</li>\n<li><strong>Grande vitesse</strong> : grand pas, régime toujours constant.</li>\n<li><strong>Survitesse</strong> (gaz poussés d'un coup) : le régulateur passe au grand pas, la charge augmente, le régime revient.</li></ul>"}, {"t": "La puissance et l'air", "kind": "info", "html": "<ul>\n<li><strong>Pression qui baisse</strong> → air moins dense → moins d'oxygène → <strong>~3 % de puissance en moins par 1 000 ft</strong> (jusqu'à ~8 000 ft).</li>\n<li><strong>Contre-pression d'échappement</strong> (échappement bouché ou trop long) → plus de travail de pompage, moins d'air frais → moins de puissance.</li>\n<li><strong>Température qui monte</strong> → <strong>~1 % de moins par 3 °C au-dessus d'ISA</strong>. Essence : plus de risque de détonation, il faut enrichir. Diesel : la quantité injectée est limitée.</li>\n<li><strong>Altitude densité</strong> (altitude pression corrigée de la température) : <strong>le facteur le plus pénalisant</strong>. Exemple : terrain à 2 000 ft par 30 °C → ~5 000 ft densité → 85 à 90 % de la puissance.</li>\n<li><strong>Humidité</strong> : effet faible (1 à 3 %).</li>\n<li><strong>Classement</strong> : 1. altitude densité ; 2. température ; 3. pression ; 4. contre-pression d'échappement ; 5. humidité.</li></ul>"}, {"t": "La suralimentation", "kind": "info", "html": "<ul>\n<li><strong>Turbocompresseur</strong> : une <strong>turbine</strong> entraînée par les gaz d'échappement fait tourner un <strong>compresseur</strong> sur le même arbre → MAP plus haute, puissance du niveau de la mer gardée en altitude.</li>\n<li><strong>Waste gate</strong> : une vanne qui fait <strong>contourner la turbine</strong> par les gaz → elle règle la vitesse du turbo et évite la surpression. Elle se <strong>ferme</strong> quand on monte.</li>\n<li><strong>Altitude-boosted</strong> (le plus courant) : MAP <strong>constante jusqu'à l'altitude critique</strong>, puis elle baisse. <strong>Ground-boosted</strong> (rare) : suralimentation max dès le sol, baisse immédiate avec l'altitude, beaucoup de chaleur.</li>\n<li><strong>Altitude critique</strong> : l'altitude max où le turbo tient la MAP nominale ; au-dessus, waste gate <strong>fermée</strong>, la MAP baisse.</li>\n<li><strong>Intercooler</strong> : refroidit l'air comprimé → plus dense (plus de puissance) et <strong>moins de détonation</strong>.</li>\n<li><strong>Temps de réponse</strong> (turbo lag) : la turbine met du temps à accélérer → réponse lente puis à-coup.</li>\n<li><strong>Compresseur mécanique</strong> (supercharger) : entraîné par le vilebrequin → <strong>pas de temps de réponse</strong>, bon à bas régime, mais il prend <strong>10 à 30 %</strong> de la puissance et perd en altitude. Le turbo récupère l'énergie perdue à l'échappement : meilleur rendement.</li></ul>"}, {"t": "Conduire le moteur", "kind": "info", "html": "<ul>\n<li><strong>Augmenter la puissance</strong> : <strong>mélange enrichi d'abord, puis les gaz</strong> (évite la détonation). Gestes souples (efforts de torsion sur le vilebrequin).</li>\n<li><strong>Réduire</strong> : le diapo écrit aussi « mélange d'abord » ; la règle classique est <strong>gaz, puis hélice, puis mélange</strong>. À confirmer avec ton instructeur.</li>\n<li><strong>Puissance décollage</strong> : la max autorisée, limitée en temps (souvent <strong>5 min</strong>) ; plein gaz, plein riche, régime max. <strong>Puissance max continue</strong> : sans limite de temps, 75 à 85 % de la puissance décollage.</li>\n<li><strong>Grand froid</strong> : huile épaisse, batterie faible, mauvaise vaporisation, Jet A-1 visqueux → lancement lent, étincelle faible. Parades : préchauffage, GPU, primer, mélange riche, hélice petit pas.</li>\n<li><strong>FADEC</strong> : une seule manette. Il gère débit, avance à l'allumage, régulateur d'hélice, mélange et protections (survitesse, surpression, surchauffe). <strong>Plus de manette de mélange ni de magnétos.</strong> Double canal, alimentations redondantes (alternateurs à aimant permanent + batterie), capteurs doublés, vote → <strong>une panne simple ne fait pas perdre le contrôle du moteur</strong>.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>Régime trop haut → <strong>grand pas</strong>. La TAS monte → <strong>le pas augmente</strong>, le régime ne bouge pas.</li>\n<li>Simple effet : perte d'huile → <strong>grand pas</strong> (pas drapeau automatique).</li>\n<li>Hélice à vitesse constante : manette d'hélice = <strong>régime</strong>, manette des gaz = <strong>MAP</strong>.</li>\n<li>Synchrophasage = synchronisation <strong>+ décalage angulaire</strong>.</li>\n<li>Altitude critique : waste gate <strong>fermée</strong>.</li>\n<li>Le facteur le plus pénalisant est l'<strong>altitude densité</strong>.</li></ul>"}], "oral": ["Définis hélice à calage fixe, à vitesse constante, drapeau, reverse, pas géométrique et recul.", "Explique le fonctionnement du régulateur quand le régime est trop haut, puis trop bas.", "Compare une hélice à simple effet et à double effet.", "Pourquoi faut-il un manomètre de MAP avec une hélice à vitesse constante ? À quoi sert le couplemètre ?", "Comment se fait la mise en drapeau automatique ? À quoi sert le réducteur ?", "Quels paramètres font baisser la puissance d'un moteur atmosphérique ? Classe-les.", "Explique le turbocompresseur, la waste gate, l'altitude critique et l'intercooler. Compare turbo et compresseur mécanique.", "Qu'apporte un FADEC sur un moteur à pistons ?"]}, "reacteur": {"cards": [{"t": "Produire de la poussée", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> (3e loi de Newton) : on <strong>accélère une masse d'air vers l'arrière</strong>, la réaction pousse l'avion vers l'avant.</li>\n<li><strong>Le trajet de l'air</strong> : entrée d'air → <strong>compresseur</strong> (haute pression) → <strong>chambre</strong> (on brûle le carburant, le gaz se dilate) → <strong>turbine</strong> (elle prélève de l'énergie pour entraîner le compresseur) → <strong>tuyère</strong> (le gaz sort très vite).</li>\n<li><strong>Formule</strong> : <strong>F = ṁ × (Ve − V0) + (Pe − P0) × Ae</strong><ul>\n<li>ṁ = débit massique (kg/s) ; Ve = vitesse d'éjection ; V0 = vitesse de l'avion ;</li>\n<li>Pe − P0 = surpression à la sortie de la tuyère ; Ae = section de sortie.</li>\n<li>Première partie = <strong>poussée de quantité de mouvement</strong> ; seconde = <strong>poussée de pression</strong>.</li></ul></li></ul>\n<p><strong>Exemple du cours</strong> : ṁ = 50 kg/s, Ve = 600 m/s, V0 = 100 m/s → 50 × 500 = 25 000 N. Surpression 20 000 Pa sur 0,3 m² → 6 000 N. <strong>Total : 31 000 N ≈ 31 kN.</strong> En subsonique, la poussée de pression est souvent petite : c'est la quantité de mouvement qui domine.</p>"}, {"t": "La poussée et la vitesse", "kind": "info", "html": "<ul>\n<li>Pour un turboréacteur simple flux, <strong>la poussée reste à peu près constante</strong> de l'arrêt jusqu'à ~<strong>M0,8 à 0,9</strong>.</li>\n<li><strong>Pourquoi</strong> : deux effets s'opposent. L'<strong>effet de vitesse</strong> : plus V0 augmente, plus Ve − V0 diminue (−). L'<strong>effet de compression dynamique</strong> (bélier) : l'air s'entasse dans l'entrée d'air, la pression et le débit montent (+). Les deux s'équilibrent.</li>\n<li>Donc : poussée au décollage ≈ en montée ≈ en croisière, jusqu'aux effets transsoniques.</li>\n<li><strong>Cycle continu</strong> : admission, compression, combustion et détente ont lieu <strong>en même temps</strong> à des endroits différents (le moteur à pistons, lui, est intermittent).</li>\n<li><strong>Vitesses dans le compresseur</strong> : vitesse absolue = composante <strong>axiale</strong> (le long de l'axe) + composante <strong>tangentielle</strong> (autour de l'axe, le tourbillon). Le rotor du compresseur <strong>augmente</strong> la vitesse tangentielle ; la turbine la <strong>diminue</strong> en prélevant l'énergie.</li></ul>"}, {"t": "Les types de turbines à gaz", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Principe</th>\n<th>Point fort</th>\n<th>Point faible</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Simple flux</strong> (turbojet)</td>\n<td>Tout l'air passe par le cœur ; jet très rapide</td>\n<td>Grande vitesse (M0,8 et +)</td>\n<td>Consomme, bruyant</td></tr>\n<tr>\n<td><strong>Double flux faible taux</strong> (0,3 à 2:1 ; M88 du Rafale 0,3:1)</td>\n<td>Petite soufflante, jet rapide</td>\n<td>Poussée spécifique élevée, petit maître-couple, léger : militaire</td>\n<td>Consomme plus, bruyant</td></tr>\n<tr>\n<td><strong>Double flux fort taux</strong> (5 à 12:1 ; A320neo 11:1, A350 9,6:1, 787 9,3:1)</td>\n<td>Grosse soufflante, la majorité de la poussée vient du flux froid</td>\n<td>Très économe, silencieux, bon rendement propulsif</td>\n<td>Gros diamètre (traînée), lourd, pas supersonique</td></tr>\n<tr>\n<td><strong>Turbopropulseur</strong></td>\n<td>Turbine → réducteur → hélice ; <strong>80 à 99 %</strong> de la poussée par l'hélice, le reste par le jet résiduel</td>\n<td>Meilleur rendement propulsif à basse vitesse (&lt; ~400 kt)</td>\n<td>Limité en vitesse</td></tr></tbody></table>\n<ul>\n<li><strong>Taux de dilution (BPR)</strong> = débit d'air <strong>secondaire</strong> (froid, qui contourne le cœur) / débit d'air <strong>primaire</strong> (chaud, qui traverse le cœur).</li>\n<li>Turbofan : poussée = jet chaud du cœur + jet froid de la soufflante.</li></ul>"}, {"t": "Corps, turbine liée, turbine libre", "kind": "info", "html": "<ul>\n<li><strong>Mono-corps</strong> : un seul arbre relie compresseur et turbine. Simple, léger, peu efficace.</li>\n<li><strong>Multi-corps</strong> (2 ou 3 arbres) : le corps <strong>BP</strong> (soufflante + turbine BP) tourne lentement, le corps <strong>HP</strong> (compresseur HP + turbine HP) tourne vite. Meilleur rendement sur toute la plage, <strong>moins de pompage</strong>, mais plus complexe et cher.</li>\n<li><strong>Puissance équivalente (EHP)</strong> d'un turbopropulseur = puissance sur l'arbre (<strong>SHP</strong>) + puissance due au jet résiduel. Exemple : 1 000 SHP + 200 = 1 200 EHP. On l'utilise car la poussée dépend de l'hélice choisie.</li>\n<li><strong>Turbine liée</strong> (coupled) : la turbine de puissance est <strong>sur le même arbre</strong> que le générateur de gaz ; tout le moteur tourne au même régime N.</li>\n<li><strong>Turbine libre</strong> : le générateur de gaz (<strong>N1</strong>) et la turbine de puissance (<strong>N2</strong>) sont sur des <strong>arbres indépendants</strong>, sans lien mécanique. Le compresseur tourne à son régime optimal, le <strong>démarrage est plus facile</strong> (moins de charge pour le démarreur), large plage de puissance <strong>sans pompage</strong>.</li></ul>"}, {"t": "Rendements, consommation, limites", "kind": "info", "html": "<ul>\n<li><strong>Rendement propulsif</strong> ηp : bon quand <strong>Ve est proche de la vitesse de l'avion</strong>. D'où : hélice et double flux meilleurs que le simple flux à vitesse modérée.</li>\n<li><strong>Rendement thermique</strong> ηth : augmente avec le <strong>taux de compression</strong> (anciens moteurs 10 à 20:1 ; double flux modernes 30 à 50:1).</li>\n<li><strong>Rendement global = ηp × ηth</strong>.</li>\n<li><strong>Consommation spécifique</strong> : réacteur = débit / <strong>poussée</strong> (turbojet 0,9 à 1,2 ; double flux fort taux 0,5 à 0,6 lb/lb/h) ; turbopropulseur = débit / <strong>puissance sur l'arbre</strong> (0,45 à 0,55 lb/hp/h).</li>\n<li><strong>Limites matériaux</strong> : la <strong>température turbine</strong> (ITT, TIT ; aubes en superalliages de nickel, 850 à 1 050 °C en continu sur une turbine liée) et le <strong>couple</strong> (réducteur, arbres).</li>\n<li><strong>Dépassement</strong> : fluage, oxydation, fissures, fusion des aubes ; dents de pignons arrachées, arbre tordu ou cisaillé, moyeu d'hélice abîmé.</li>\n<li><strong>Tout dépassement se déclare</strong> immédiatement, au carnet de route : il peut cacher des dégâts (endoscopie, maintenance, dépose).</li></ul>"}, {"t": "L'entrée d'air", "kind": "info", "html": "<ul>\n<li><strong>Rôles</strong> : donner au compresseur un <strong>flux régulier et homogène</strong>, <strong>ralentir l'air</strong> pour augmenter sa pression statique (effet bélier), protéger des corps étrangers, limiter la turbulence, permettre l'antigivrage.</li>\n<li><strong>Entrée pitot subsonique</strong> : face au vent, elle transforme la pression dynamique en pression statique. Simple et efficace en subsonique.</li>\n<li><strong>Problèmes</strong> :<ul>\n<li><strong>décollement</strong> à forte incidence (lèvre) → décrochage compresseur, pompage, extinction, vibrations ;</li>\n<li><strong>ingestion</strong> (oiseau, grêle, débris) → aubes abîmées, balourd, pompage, panne ;</li>\n<li><strong>givrage</strong> → flux perturbé, pompage, perte de débit et de puissance, extinction possible ;</li>\n<li><strong>forte turbulence</strong> → incidence et vitesse qui varient, petits pompages (risque d'extinction faible).</li></ul></li></ul>"}, {"t": "Le compresseur", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th></th>\n<th>Centrifuge</th>\n<th>Axial</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Principe</strong></td>\n<td>Un <strong>rouet</strong> accélère l'air vers l'extérieur ; le <strong>diffuseur</strong> fixe transforme la vitesse en pression</td>\n<td>Les <strong>rotors</strong> accélèrent l'air et lui donnent du tourbillon ; les <strong>stators</strong> le redressent et le transforment en pression</td></tr>\n<tr>\n<td><strong>Taux par étage</strong></td>\n<td><strong>4 à 6:1</strong></td>\n<td><strong>1,2 à 1,5:1</strong>, mais beaucoup d'étages</td></tr>\n<tr>\n<td><strong>Corps étrangers</strong></td>\n<td><strong>Peu sensible</strong> (les particules sont rejetées vers l'extérieur)</td>\n<td><strong>Très sensible</strong> (grande entrée, aubes fines)</td></tr>\n<tr>\n<td><strong>Usage</strong></td>\n<td>Petits moteurs, APU</td>\n<td>Gros réacteurs</td></tr></tbody></table>\n<ul>\n<li>Dans le compresseur : vitesse axiale à peu près constante (légère baisse), <strong>pression et température montent</strong>.</li>\n<li><strong>Veine convergente</strong> : la section <strong>diminue</strong> vers l'arrière pour garder une vitesse axiale constante malgré la compression (sinon les aubes décrochent).</li>\n<li><strong>Vrillage des aubes</strong> : le pied tourne moins vite que le bout ; on vrille l'aube pour garder la <strong>même incidence</strong> sur toute sa longueur.</li>\n<li><strong>Aubes directrices d'entrée (IGV)</strong> : orientent l'air sur le premier rotor ; variables, elles gardent la marge au pompage hors du point de conception.</li>\n<li><strong>Plus d'étages centrifuges</strong> : taux plus élevé, mais plus lourd, plus cher, plus dur à refroidir, plus de risque de pompage.</li>\n<li><strong>Pertes en bout d'aube</strong> : carénages de bout, joints labyrinthe, rainures dans le carter, aubes allongées. <strong>Flexion et flottement des aubes</strong> : aubes vrillées et effilées, matériaux rigides (titane, composites), amortisseurs.</li>\n<li><strong>Cliquetis au sol</strong> quand le fan tourne lentement (arrêt, moulinet) : les aubes bougent dans leur logement faute de force centrifuge. <strong>Normal.</strong></li></ul>"}, {"t": "Décrochage compresseur et pompage", "kind": "info", "html": "<ul>\n<li><strong>Décrochage compresseur</strong> : un <strong>décollement local</strong> sur une aube dont l'incidence est trop forte → l'étage comprime moins.</li>\n<li><strong>Pompage</strong> (surge) : l'écoulement <strong>s'arrête ou s'inverse</strong> dans tout le compresseur → oscillations violentes de pression.</li>\n<li><strong>Signes</strong> : <strong>détonation forte</strong> ou grondement, <strong>flammes</strong> à l'entrée ou à l'échappement, vibrations, <strong>chute rapide de N1/N2</strong>, <strong>pic d'EGT/ITT</strong>, perte de poussée ou de couple.</li>\n<li><strong>Causes</strong> : faible vitesse + régime élevé, <strong>accélération brutale</strong> de la manette, forte incidence ou turbulence, aubes abîmées, givrage ou obstruction.</li>\n<li><strong>Parades</strong> : <strong>IGV et stators à calage variable</strong> (moins d'incidence à bas régime), <strong>vannes de décharge</strong> (on évacue de l'air entre deux étages), <strong>multi-corps</strong>.</li>\n<li><strong>Champ compresseur</strong> : débit massique en abscisse, taux de compression en ordonnée. La <strong>ligne de pompage</strong> est la limite ; la <strong>marge au pompage</strong> est l'écart entre la ligne de fonctionnement et la ligne de pompage.</li>\n<li><strong>Diffuseur</strong> (en sortie du compresseur centrifuge) : ralentit l'air rapide et le transforme en pression ; à aubes (fixes ou variables) ou lisse.</li></ul>"}, {"t": "La chambre de combustion", "kind": "info", "html": "<ul>\n<li><strong>Rôle</strong> : ajouter de l'énergie en brûlant le carburant, monter la température au maximum que la turbine supporte, avec <strong>peu de perte de pression</strong> et une combustion complète.</li>\n<li><strong>Exigences</strong> : bonne richesse, bon mélange, temps de séjour suffisant, allumeurs au démarrage, flamme stable (ni soufflée ni remontée), perte de charge &lt; 5 à 7 %, peu d'émissions, température homogène à l'entrée turbine.</li>\n<li><strong>Ralentir l'air</strong> : il sort du compresseur à 150 à 200 m/s, il faut <strong>20 à 50 m/s</strong> pour que la flamme tienne. Un <strong>diffuseur</strong> (snout) élargit la veine et crée une zone de recirculation.</li>\n<li><strong>Vrille d'entrée</strong> (swirler) : donne un tourbillon à l'air primaire → <strong>recirculation qui accroche la flamme</strong>, meilleur mélange, flamme stable, chambre compacte.</li>\n<li><strong>Air primaire</strong> (20 à 30 %) : par la vrille, il brûle avec le carburant à richesse <strong>stœchiométrique</strong> (14,7 à 18:1). <strong>Air secondaire</strong> (70 à 80 %) : par des trous de dilution, il <strong>refroidit</strong> les gaz et répartit la température. <strong>Richesse globale très pauvre : 40 à 60:1</strong>.</li>\n<li>Dans la chambre : <strong>pression statique presque constante</strong> (perte 3 à 7 %), <strong>température qui monte fortement</strong> (400-600 °C → 1 200-1 600 °C), vitesse axiale faible.</li>\n<li><strong>Vannes de purge</strong> au point bas : vidangent le carburant après un arrêt ou un démarrage raté (sinon feu au démarrage suivant).</li>\n<li><strong>Types</strong> : <strong>tubulaire</strong> (6 à 12 tubes, simple, points chauds) → <strong>tubo-annulaire</strong> (meilleure répartition, anciens moteurs) → <strong>annulaire</strong> (une seule chambre en anneau : température homogène, moins de pertes, <strong>standard moderne</strong>) → <strong>annulaire à flux inversé</strong> (compact : petits moteurs, APU).</li></ul>"}, {"t": "La turbine", "kind": "info", "html": "<ul>\n<li><strong>Rôle</strong> : prélever l'énergie des gaz pour entraîner le compresseur (et l'hélice ou la turbine libre). Le reste de l'énergie part dans la tuyère.</li>\n<li><strong>Action</strong> (impulse) : toute la détente se fait dans le <strong>distributeur</strong> (stator) ; le rotor ne fait que dévier le jet rapide. Simple, robuste.</li>\n<li><strong>Réaction</strong> : la détente se fait aussi <strong>dans le rotor</strong> (profil d'aile), le gaz accélère et pousse par réaction. Meilleur rendement.</li>\n<li><strong>Action-réaction</strong> : le mélange des deux, <strong>le plus courant</strong>.</li>\n<li><strong>Un étage</strong> = <strong>distributeur</strong> fixe (accélère et oriente le gaz, transforme pression en vitesse) + <strong>aubes mobiles</strong> (prennent l'énergie, donnent du couple) + <strong>disque</strong> (transmet le couple à l'arbre).</li>\n<li>Dans la turbine : <strong>pression et température baissent</strong>.</li>\n<li><strong>Pertes en bout d'aube</strong> (2 à 5 %) : carénages de bout, joints labyrinthe, rainures, <strong>contrôle actif du jeu</strong> (de l'air du compresseur refroidit le carter pour qu'il se contracte à forte puissance).</li>\n<li><strong>La poussée est limitée par la TIT</strong>, le point le plus chaud du moteur (1 400 à 1 700 °C avec refroidissement).</li>\n<li><strong>Contraintes</strong> : thermiques (gaz à 1 400 °C, pied d'aube plus froid) et mécaniques (<strong>force centrifuge</strong>, flexion due au gaz, disques très tendus). Solutions : refroidissement interne, <strong>aubes monocristallines</strong>, barrières thermiques, refroidissement des disques.</li></ul>"}, {"t": "La tuyère et le bruit", "kind": "info", "html": "<ul>\n<li><strong>Cône d'échappement</strong> : flux régulier en sortie de turbine. <strong>Tuyau d'éjection</strong> : amène les gaz à la tuyère avec peu de pertes (mélangeurs, silencieux). <strong>Tuyère</strong> convergente ou convergente-divergente : <strong>accélère</strong> les gaz → poussée.</li>\n<li>Dans l'échappement : pression et température baissent, <strong>vitesse qui augmente</strong> fortement.</li>\n<li><strong>Tuyère bloquée</strong> (choked) : la vitesse atteint <strong>Mach 1 au col</strong> ; baisser encore la pression en aval n'accélère plus le gaz, le <strong>débit est maximal</strong>. Pour un jet supersonique, il faut une tuyère <strong>convergente-divergente</strong> (moteurs à post-combustion, fusées).</li>\n<li><strong>Sources de bruit</strong> : le jet (mélange turbulent avec l'air), la soufflante (interaction rotor-stator), turbine et compresseur (aigu), combustion.</li>\n<li><strong>Réduction</strong> : mélangeurs et <strong>chevrons</strong>, tuyères multitubes, <strong>revêtements acoustiques</strong>, <strong>fort taux de dilution</strong> (le flux froid entoure le jet chaud, moins d'écart de vitesse), et en exploitation puissance réduite et procédures antibruit.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>La <strong>turbine</strong> entraîne le compresseur ; c'est la <strong>tuyère</strong> qui accélère les gaz.</li>\n<li>En subsonique, la poussée d'un turboréacteur est <strong>à peu près constante</strong> avec la vitesse.</li>\n<li>BPR = flux <strong>froid</strong> / flux <strong>chaud</strong>.</li>\n<li><strong>Centrifuge</strong> : gros taux par étage, peu sensible aux corps étrangers. <strong>Axial</strong> : petit taux par étage, sensible.</li>\n<li>Dans la chambre, la <strong>pression reste presque constante</strong> ; la température monte.</li>\n<li>La poussée max est limitée par la <strong>TIT</strong>.</li>\n<li>Cliquetis du fan à l'arrêt : <strong>normal</strong>.</li></ul>"}], "oral": ["Énonce la formule de la poussée et calcule-la pour ṁ = 80 kg/s, Ve = 500 m/s, V0 = 150 m/s, sans poussée de pression.", "Pourquoi la poussée d'un turboréacteur reste-t-elle à peu près constante en subsonique ?", "Compare turboréacteur, double flux faible et fort taux, et turbopropulseur. Définis le taux de dilution.", "Différencie turbine liée et turbine libre. Avantages de la turbine libre ?", "Définis les rendements propulsif, thermique et global.", "Compare les compresseurs centrifuge et axial. Pourquoi la veine est-elle convergente et les aubes vrillées ?", "Différencie décrochage compresseur et pompage : causes, signes, parades.", "Décris le fonctionnement de la chambre de combustion (air primaire, secondaire, vrille, richesse).", "Compare turbines à action et à réaction. Qu'est-ce qui limite la poussée maximale ?", "Qu'est-ce qu'une tuyère bloquée ? Comment réduit-on le bruit d'un turboréacteur ?"]}, "demarrage": {"cards": [{"t": "Le circuit carburant du moteur", "kind": "info", "html": "<ul>\n<li><strong>Filtres</strong> : retirent impuretés et eau.</li>\n<li><strong>Pompe BP</strong> : gave la pompe HP (pression positive), <strong>évite la cavitation</strong>.</li>\n<li><strong>Pompe HP</strong> : envoie le carburant haute pression au régulateur et aux injecteurs.<ul>\n<li><strong>à engrenages</strong> : simple, fiable, cylindrée fixe (petits moteurs) ;</li>\n<li><strong>à plateau inclinable</strong> : cylindrée variable, plus efficace et précise (gros moteurs).</li></ul></li>\n<li><strong>Rampe</strong> : distribue le carburant aux injecteurs. <strong>Injecteurs</strong> : pulvérisent finement le carburant.</li>\n<li><strong>Robinet HP</strong> : coupe l'alimentation du moteur (poignée feu, urgence).</li>\n<li><strong>Régulateur (FCU)</strong> ou bloc hydromécanique : dose exactement le carburant.</li></ul>"}, {"t": "Le régulateur carburant (FCU)", "kind": "info", "html": "<ul>\n<li><strong>Tâches</strong> :<ul>\n<li>doser le carburant pour la poussée demandée ;</li>\n<li>garder la bonne richesse dans toutes les conditions ;</li>\n<li><strong>limiter le débit pendant l'accélération pour éviter le pompage</strong> ;</li>\n<li>protéger automatiquement (surchauffe, survitesse) ;</li>\n<li>corriger selon l'altitude, la température et la vitesse.</li></ul></li>\n<li><strong>Entrées</strong> : position de la manette (<strong>TLA</strong>), régimes <strong>N1/N2</strong>, température et pression d'entrée compresseur (<strong>T2, P2</strong>), <strong>EGT/ITT</strong>, pression et température extérieures, état des prélèvements d'air, vitesse.</li></ul>"}, {"t": "La régulation et le FADEC", "kind": "info", "html": "<ul>\n<li><strong>Évolution</strong> : hydromécanique (ancien) → hydromécanique + superviseur électronique à autorité limitée → FADEC simple canal avec secours hydromécanique → <strong>FADEC double canal sans secours</strong> (standard actuel).</li>\n<li><strong>Tâches</strong> : régler le débit pour la poussée voulue, rester dans les limites (température, régime, pression), protéger, accélérer et décélérer en douceur, optimiser la consommation, dialoguer avec l'avion (automanette).</li>\n<li><strong>FADEC</strong> = calculateur moteur à <strong>pleine autorité</strong>, avec <strong>deux canaux indépendants A et B</strong>. Son cœur est l'<strong>EEC</strong> : loi carburant, démarrage, gestion de la poussée, protections, géométrie variable et vannes de décharge, détection de panne et changement de canal.</li>\n<li>La manette envoie un <strong>signal électrique</strong> (capteurs <strong>TLA</strong>) ; le FADEC calcule la poussée ou le régime cible.</li>\n<li><strong>Capteurs</strong> : N1, N2, EGT, pressions compresseur (P2, P3), température d'entrée, pression carburant, conditions extérieures.</li>\n<li><strong>Actionneurs</strong> : doseur (<strong>FMU</strong>), <strong>stators variables</strong> (VSV : stabilité, anti-pompage), <strong>vannes de décharge</strong> (stabiliser au démarrage et en accélération, fournir l'air à l'avion), <strong>contrôle actif du jeu</strong>.</li>\n<li><strong>Protections automatiques</strong>, non contournables en temps normal : <strong>EGT</strong> (réduit le débit, limite l'accélération) ; <strong>survitesse N1/N2</strong> (réduit le débit, et au pire <strong>coupe le moteur</strong>).</li>\n<li><strong>Redondance</strong> : chaque canal a sa propre alimentation (<strong>PMA</strong>, alternateur à aimant permanent, + batterie de secours) ; capteurs et faisceaux doublés ; les canaux comparent en permanence leurs données. Un capteur en panne : la donnée fausse est <strong>rejetée</strong>, l'autre canal la fournit. <strong>Pas de perte de contrôle.</strong></li></ul>"}, {"t": "Lubrification et boîtier d'accessoires", "kind": "info", "html": "<ul>\n<li><strong>Rôles</strong> : graisser roulements et pignons, refroidir, nettoyer, protéger de la corrosion, amortir.</li>\n<li><strong>Composants</strong> : réservoir avec <strong>déshuileur centrifuge</strong> (sépare l'air), <strong>pompe de pression</strong>, <strong>pompes de récupération</strong>, filtres avec by-pass, puisards, <strong>détecteurs de limaille</strong> (bouchons magnétiques : <strong>alerte précoce d'usure</strong>), radiateurs <strong>air/huile ou carburant/huile</strong>.</li>\n<li><strong>Roulements</strong> : chaque attelage a au moins <strong>un roulement à billes</strong> (charges <strong>axiales et radiales</strong>) et <strong>deux à rouleaux</strong> ou plus (charges radiales seulement).</li>\n<li><strong>Étanchéité</strong> : <strong>joints labyrinthe pressurisés par l'air du compresseur</strong> → l'huile ne fuit pas dans la veine, les gaz n'entrent pas dans l'huile.</li>\n<li><strong>Boîtier d'accessoires</strong> : entraîné par le <strong>corps HP</strong> par un arbre de renvoi, lubrifié par le circuit d'huile du moteur. Il entraîne pompe carburant, pompes à huile, pompe hydraulique, génératrices, démarreur.</li></ul>"}, {"t": "L'allumage et le démarreur", "kind": "info", "html": "<ul>\n<li><strong>Allumage</strong> : une étincelle très énergétique pour allumer le mélange au démarrage, parfois en continu. <strong>Excitateurs</strong> (condensateurs haute énergie) + <strong>allumeurs</strong> à décharge de surface dans la chambre. <strong>Deux systèmes indépendants</strong> : on peut démarrer sur un seul.</li>\n<li><strong>Modes</strong> : <strong>démarrage</strong> (les deux allumeurs) ; <strong>allumage continu</strong> (risque d'extinction : givrage, forte pluie, turbulence ; manuel ou auto) ; <strong>rallumage automatique</strong> par le FADEC s'il détecte une extinction.</li>\n<li><strong>Démarreur</strong> : <strong>électrique</strong> (moteur DC ou AC à fort couple, batterie ou groupe de parc) ou <strong>pneumatique</strong> (turbine à air alimentée par l'<strong>APU</strong>, le groupe de parc ou le <strong>cross-bleed</strong>).</li>\n<li><strong>Principe</strong> : le démarreur fait tourner le compresseur → l'air circule → carburant + allumage → <strong>allumage</strong> (light-off) → le moteur accélère jusqu'au <strong>régime autonome</strong> → coupure du démarreur.</li></ul>"}, {"t": "La séquence de démarrage", "kind": "info", "html": "<ol>\n<li>Démarreur ON (ou APU en marche, puis lancement de la séquence).</li>\n<li><strong>Carburant ouvert vers 15 à 20 % de N2.</strong></li>\n<li><strong>Allumage</strong> : l'<strong>EGT monte</strong> (light-off).</li>\n<li>Le moteur accélère jusqu'au <strong>régime autonome</strong>.</li>\n<li>Coupure du démarreur.</li></ol>\n<ul>\n<li><strong>En vol</strong> (rallumage) : le <strong>moulinet</strong> remplace le démarreur, dans l'<strong>enveloppe de rallumage</strong> (selon vitesse et altitude).</li>\n<li><strong>Régime autonome</strong> (self-sustaining) : le régime minimum où le moteur produit assez d'énergie pour <strong>accélérer seul</strong>, sans démarreur.</li></ul>"}, {"t": "Les inverseurs de poussée", "kind": "info", "html": "<ul>\n<li><strong>Principe</strong> : renvoyer le flux vers l'avant pour freiner à l'atterrissage → distance plus courte, moins d'usure des freins.</li>\n<li><strong>Types</strong> : <strong>flux chaud</strong> (coquilles ou clamshell qui se ferment derrière la tuyère : anciens jets) ; <strong>flux froid</strong> (portes de blocage qui ferment le canal de soufflante + <strong>grilles en cascade</strong> qui renvoient l'air vers l'avant : double flux modernes, le plus courant).</li>\n<li><strong>Composants</strong> : manette de reverse, puissance hydraulique ou pneumatique, vérins, portes ou grilles, voyants REV.</li>\n<li><strong>Inconvénients</strong> : masse, complexité, <strong>réingestion</strong> de l'air renvoyé (corps étrangers).</li>\n<li><strong>Protections</strong> contre un déploiement en vol : <strong>contacteur train</strong> (au sol seulement), verrou sur la manette, logique <strong>FADEC</strong> (inhibé au-dessus d'une vitesse ou en vol), <strong>retour automatique</strong> (auto-stow).</li>\n<li><strong>Voyants</strong> : <strong>REV ambre = en transit</strong> ; <strong>REV vert = déployé</strong> et en fonctionnement.</li></ul>"}, {"t": "Les régimes certifiés", "kind": "info", "html": "<ul>\n<li><strong>MTO</strong> (décollage) : poussée max pour le décollage et la montée initiale, <strong>limitée en temps</strong> (en général <strong>5 min</strong>), trait rouge.</li>\n<li><strong>MCT</strong> (max continu) : sans limite de temps ; montée, croisière, <strong>vol sur un moteur</strong>.</li>\n<li><strong>MCL</strong> (max montée) : égal ou un peu sous MTO/MCT ; pour la montée prolongée, limité selon N1/N2, EGT, ITT ; optimisé pour la consommation et la durée de vie.</li>\n<li><strong>Temps d'accélération</strong> (spool-up, ralenti → poussée décollage) : <strong>2 à 8 s</strong>. Critique en <strong>remise de gaz</strong>. Le FADEC accélère au plus vite sans pompage ; un ralenti vol plus haut le raccourcit.</li></ul>"}, {"t": "Ralentis et paramètres", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Ralenti</th>\n<th>N1</th>\n<th>Pourquoi</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Sol</strong></td>\n<td>~40 à 60 %</td>\n<td>Moins de bruit, de carburant et de souffle</td></tr>\n<tr>\n<td><strong>Vol</strong></td>\n<td>~60 à 75 %</td>\n<td><strong>Accélération rapide</strong> pour la remise de gaz ; assez d'air pour l'antigivrage, l'électricité, l'hydraulique. <strong>Plus haut avec l'antigivrage ON</strong></td></tr></tbody></table>\n<ul>\n<li>Séparation ralenti sol / vol : butée mécanique sur la manette (levée à la main ou par le contacteur train) ou logique d'automanette.</li>\n<li><strong>Paramètres de poussée</strong> : <strong>N1</strong> (référence principale des double flux, en % ) ; N2 ; <strong>EPR</strong> (anciens moteurs) ; <strong>couple</strong> (référence des turbopropulseurs) ; <strong>ITT/TIT ou EGT</strong> (paramètre <strong>limitant</strong>) ; débit carburant.</li></ul>"}, {"t": "Turbopropulseur : alpha, bêta, reverse", "kind": "info", "html": "<ul>\n<li><strong>Plage alpha</strong> : vol normal ; le <strong>régulateur</strong> gère le pas (vitesse constante) ; la manette dose le carburant.</li>\n<li><strong>Plage bêta</strong> : au sol, sous le ralenti, jusqu'au reverse max ; <strong>la manette commande directement le pas</strong> (sans régulateur). Pour le roulage.</li>\n<li><strong>Reverse</strong> : pas négatif, freinage ; verrou de sécurité au sol (contacteur train).</li>\n<li><strong>Bêta par erreur en vol</strong> : <strong>traînée brutale</strong>, perte de vitesse (décrochage), <strong>lacet et roulis violents</strong> si un seul moteur passe en bêta, survitesse ou rupture d'hélice possible. Protections : verrous (contacteur train, contacteur de vitesse), FADEC. (Certains avions autorisent un peu de bêta en approche comme aérofrein.)</li></ul>"}, {"t": "Surveiller le moteur", "kind": "info", "html": "<ul>\n<li><strong>Engine trending</strong> : un moteur se dégrade <strong>progressivement</strong>, il dérive. On suit EGT, N1, N2, débit, vibrations, huile et on compare à une référence (moteur neuf ou sortant de maintenance) → anticiper la maintenance, moins de déposes imprévues.</li>\n<li><strong>EGT</strong>, mesurée <strong>après la turbine BP</strong> : l'image de la <strong>contrainte thermique</strong> de la turbine. Trait rouge = maximum.<ul>\n<li><strong>Accélération</strong> : le carburant augmente plus vite que l'air → mélange riche → <strong>pic d'EGT normal</strong> (le FADEC limite).</li>\n<li><strong>Décélération</strong> : mélange pauvre → l'EGT baisse puis se stabilise.</li>\n<li><strong>Dépassement</strong> : fluage, frottement en bout d'aube, oxydation, fissures, fusion, rupture non confinée. Action : réduire la puissance, chercher une fuite de prélèvement ou un capteur faux. <strong>Toujours déclarer</strong> (valeur et durée).</li></ul></li>\n<li><strong>Inverseurs à basse vitesse</strong> : ingestion de débris, instabilité directionnelle, pompage → inhibés sous <strong>~60 à 80 kt</strong>.</li></ul>"}, {"t": "Les pannes mécaniques", "kind": "info", "html": "<ul>\n<li><strong>Grippage</strong> : blocage soudain des pièces tournantes. Causes : manque d'huile, roulement qui lâche (surchauffe, pollution), corps étranger, boîtier d'accessoires, surcouple ou survitesse.</li>\n<li><strong>Fuite de l'échangeur carburant/huile</strong> :<ul>\n<li>pression <strong>huile &gt; carburant</strong> → l'huile pollue le carburant → combustion perturbée, moteur rugueux, extinction possible ;</li>\n<li>pression <strong>carburant &gt; huile</strong> → le carburant <strong>dilue l'huile</strong> → <strong>risque de feu</strong>, viscosité trop basse, roulements qui lâchent.</li></ul></li>\n<li><strong>Filtre à huile colmaté</strong> : le by-pass s'ouvre, l'huile n'est plus filtrée, usure accélérée ; alarme de pression basse ; dégâts si le by-pass ne s'ouvre pas.</li>\n<li><strong>Diagnostic</strong> :<ul>\n<li>vibrations fortes → roulement ou aube ;</li>\n<li><strong>EGT haute + N1 bas</strong> → turbine endommagée ;</li>\n<li>pression d'huile basse + température haute → lubrification ;</li>\n<li>chute brutale de couple → réducteur ou arbre ;</li>\n<li>débit plus fort pour la même poussée → rendement dégradé (fuites compresseur ou turbine).</li></ul></li></ul>"}, {"t": "Les démarrages ratés", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th>Cas</th>\n<th>Signes</th>\n<th>Cause probable</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Faux démarrage</strong> (sec ou humide)</td>\n<td><strong>Pas d'allumage</strong>, EGT qui reste basse, N1 qui ne monte pas</td>\n<td>Pas de carburant ou pas d'allumage, mauvaise loi carburant</td></tr>\n<tr>\n<td><strong>Feu de tuyère</strong> (torching)</td>\n<td><strong>Flammes à l'échappement</strong>, EGT haute, N1 qui ne monte pas</td>\n<td>Trop de carburant, qui brûle dans l'échappement</td></tr>\n<tr>\n<td><strong>Démarrage chaud</strong> (hot start)</td>\n<td><strong>EGT qui monte très vite</strong> et dépasse le trait rouge</td>\n<td>Trop de carburant, pas assez d'air</td></tr>\n<tr>\n<td><strong>Démarrage bloqué</strong> (hung)</td>\n<td>N1 qui se stabilise <strong>sous le régime autonome</strong></td>\n<td>Démarreur trop faible, régulation carburant</td></tr>\n<tr>\n<td><strong>N1 à zéro</strong></td>\n<td>N1 ne tourne pas alors que N2 tourne</td>\n<td>Moteur grippé, panne électrique</td></tr>\n<tr>\n<td><strong>Pas d'indications FADEC</strong></td>\n<td>Plus de données moteur à l'ECAM/EICAS</td>\n<td>FADEC non alimenté, capteur ou câblage</td></tr></tbody></table>\n<p><strong>Enveloppe de rallumage</strong> : la plage altitude/vitesse où l'on peut rallumer en vol. Elle dépend du débit d'air (combustion), du régime de moulinet et des limites de température. <strong>Limite basse</strong> = vitesse mini pour un moulinet suffisant ; <strong>limite haute</strong> = altitude max (air assez dense).</p>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>La pompe <strong>BP</strong> évite la <strong>cavitation</strong> de la pompe HP.</li>\n<li>Le FCU <strong>limite</strong> le débit en accélération : c'est une protection anti-pompage.</li>\n<li>FADEC moderne = <strong>double canal sans secours</strong> hydromécanique.</li>\n<li>Boîtier d'accessoires entraîné par le corps <strong>HP</strong>.</li>\n<li><strong>REV ambre</strong> = transit ; <strong>REV vert</strong> = déployé.</li>\n<li><strong>Hot start</strong> = EGT qui s'emballe ; <strong>hung start</strong> = régime bloqué sous l'autonome ; <strong>faux démarrage</strong> = pas d'allumage.</li>\n<li>Fuite d'échangeur avec carburant &gt; huile : <strong>feu</strong> et huile diluée.</li>\n<li>Un pic d'EGT pendant une <strong>accélération</strong> est <strong>normal</strong>.</li></ul>"}], "oral": ["Décris le circuit carburant d'un turboréacteur et le rôle de chaque pompe.", "Quelles sont les tâches du FCU et ses paramètres d'entrée ?", "Qu'est-ce qu'un FADEC ? Décris ses fonctions, ses protections et sa redondance.", "Décris le circuit de lubrification et l'étanchéité des paliers. Quel corps entraîne le boîtier d'accessoires ?", "Décris le système d'allumage et ses modes.", "Donne la séquence de démarrage d'un turbofan. Qu'est-ce que le régime autonome ?", "Décris les deux types d'inverseurs et leurs protections contre un déploiement en vol.", "Pourquoi le ralenti vol est-il plus élevé que le ralenti sol ?", "Décris les plages alpha, bêta et reverse d'un turbopropulseur et le danger du bêta en vol.", "Cite les démarrages ratés avec leurs signes et leurs causes."]}, "perfs": {"cards": [{"t": "La poussée et l'altitude", "kind": "info", "html": "<ul>\n<li><strong>Altitude qui monte, TAS constante</strong> : l'air est moins dense → <strong>le débit massique baisse</strong> → <strong>la poussée baisse</strong> (~3 à 4 % par 1 000 ft jusqu'à ~25 000 ft, puis plus lentement).</li>\n<li><strong>La consommation spécifique augmente</strong> avec l'altitude (~5 à 10 % par 10 000 ft selon le cours) : il faut brûler relativement plus de carburant pour la même poussée.</li></ul>"}, {"t": "La poussée et la vitesse", "kind": "info", "html": "<ul>\n<li><strong>TAS qui monte, altitude constante</strong> (subsonique) : la poussée reste <strong>à peu près constante</strong> ou baisse légèrement. L'effet bélier augmente un peu le débit (+), mais l'écart Ve − V0 diminue (−).</li>\n<li><strong>La consommation spécifique baisse légèrement</strong> quand la TAS augmente : le rendement propulsif s'améliore quand la vitesse de l'avion se rapproche de la vitesse d'éjection.</li></ul>"}, {"t": "Le moteur à poussée plate (flat-rated)", "kind": "info", "html": "<ul>\n<li><strong>Définition</strong> : la poussée de décollage reste <strong>constante jusqu'à une température extérieure donnée</strong> (la température de flat rating), puis elle baisse.</li>\n<li><strong>Sous cette température</strong> : poussée = valeur nominale ; quand l'OAT monte, la <strong>TIT augmente</strong> (le moteur travaille plus pour garder la poussée), le régime peut monter un peu.</li>\n<li><strong>À cette température</strong> : la TIT atteint sa <strong>limite</strong>.</li>\n<li><strong>Au-dessus</strong> : la TIT est <strong>figée</strong> à sa limite → <strong>la poussée baisse</strong>.</li></ul>\n<p><strong>Pour comprendre</strong> : le moteur pourrait donner plus de poussée par temps froid, mais on la plafonne. Par temps chaud, c'est la température turbine qui devient la limite.</p>"}, {"t": "L'EPR", "kind": "info", "html": "<ul>\n<li><strong>EPR</strong> (engine pressure ratio) = <strong>pression en sortie de turbine / pression en entrée de compresseur</strong>.</li>\n<li>Paramètre principal de poussée sur beaucoup d'anciens turboréacteurs et de double flux à faible taux. Plus d'EPR = plus de poussée.</li></ul>"}, {"t": "Poussée réduite (FLEX) ou détarée (DERATE)", "kind": "info", "html": "<table>\n<thead>\n<tr>\n<th></th>\n<th>Poussée réduite (FLEX)</th>\n<th>Poussée détarée (DERATE)</th></tr></thead>\n<tbody>\n<tr>\n<td><strong>Principe</strong></td>\n<td>On entre une <strong>température supposée</strong> plus haute que la réelle (assumed temperature) : on « trompe » la loi de régulation</td>\n<td>Une <strong>réduction fixe et certifiée</strong> de la poussée max (TO1 = −10 %, TO2 = −20 %) : le FADEC <strong>plafonne</strong> la poussée</td></tr>\n<tr>\n<td><strong>Réglage</strong></td>\n<td><strong>Continu</strong>, optimisé à chaque départ</td>\n<td><strong>Par paliers</strong></td></tr>\n<tr>\n<td><strong>Avantages</strong></td>\n<td>Durée de vie du moteur (marge d'EGT), maintenance, carburant au décollage, bruit</td>\n<td>Robuste, simple, moins de calculs, performances prévisibles</td></tr>\n<tr>\n<td><strong>Limites</strong></td>\n<td>Calcul précis indispensable (risque d'erreur), sensible aux changements (vent, contamination) ; <strong>interdit sur piste contaminée, avec risque de cisaillement de vent</strong>, parfois avec l'antigivrage ON</td>\n<td>Moins optimisé, marge parfois inutilisée ; il faut quand même choisir le bon palier</td></tr></tbody></table>\n<p><strong>La différence clé</strong> : en FLEX, le moteur garde <strong>toute sa capacité</strong> (le pilote peut pousser les manettes à fond) ; en DERATE, la poussée max est <strong>réellement plafonnée</strong> (c'est une limite certifiée).</p>"}, {"t": "L'effet des prélèvements d'air", "kind": "info", "html": "<p>Quand on prélève de l'air au compresseur (bleed pour la clim, l'antigivrage) :\n- <strong>régime</strong> : légère baisse (moins de débit dans le cœur) ;\n- <strong>EGT / TIT</strong> : <strong>en hausse</strong> (il faut plus de carburant pour garder la poussée) ;\n- <strong>poussée</strong> : <strong>en baisse</strong> (moins de débit, moins de quantité de mouvement) ;\n- <strong>consommation spécifique</strong> : <strong>en hausse</strong> (plus de carburant pour moins de poussée).</p>"}, {"t": "L'APU", "kind": "info", "html": "<ul>\n<li><strong>APU</strong> (groupe auxiliaire de puissance) : une <strong>petite turbine à gaz</strong>, en général dans la <strong>queue</strong> des jets.</li>\n<li><strong>Rôles</strong> :<ul>\n<li><strong>électricité au sol</strong> quand les moteurs sont arrêtés ;</li>\n<li><strong>air de prélèvement pour démarrer les moteurs</strong> ;</li>\n<li>secours électrique et pneumatique <strong>en vol</strong> ;</li>\n<li><strong>climatisation et pressurisation au sol</strong>.</li></ul></li>\n<li><strong>Entrées d'air</strong> : <strong>affleurante</strong> (flush, la plus courante : peu de traînée, mais il faut une <strong>porte</strong> qui s'ouvre) ou <strong>écope</strong> (scoop, anciens modèles : plus de traînée, plus simple, sans porte).</li>\n<li><strong>Altitudes</strong> : <strong>altitude max de fonctionnement</strong> (FL350 à FL410 selon le modèle) <strong>&gt; altitude max de démarrage</strong> (FL250 à FL300), car le démarrage demande plus de couple et plus d'air.</li>\n<li><strong>Commandes et indications</strong> : bouton start/stop, générateur, bleed ; régime, EGT, pression et température d'huile, charge du générateur, pression bleed ; alarmes feu, panne, huile, EGT haute.</li>\n<li><strong>Arrêts automatiques</strong> (non contournables dans la plupart des cas) : <strong>EGT haute</strong>, <strong>pression d'huile basse</strong>, température d'huile haute, <strong>survitesse</strong>, sous-vitesse (extinction), <strong>inversion du flux bleed</strong>, <strong>feu</strong>. Après un arrêt automatique, il faut en général une <strong>action de maintenance</strong> avant de redémarrer.</li></ul>"}, {"t": "Les pièges", "kind": "trap", "html": "<ul>\n<li>À TAS constante, quand on monte : poussée <strong>en baisse</strong>, consommation spécifique <strong>en hausse</strong>.</li>\n<li>Flat rating : sous la température de flat rating, la poussée est <strong>constante</strong> et c'est la <strong>TIT</strong> qui monte.</li>\n<li><strong>FLEX</strong> = température supposée, réglage continu, moteur pas limité. <strong>DERATE</strong> = paliers certifiés, poussée vraiment plafonnée.</li>\n<li>FLEX interdit sur piste <strong>contaminée</strong> et avec risque de <strong>cisaillement de vent</strong>.</li>\n<li>Prélever de l'air : poussée <strong>en baisse</strong>, EGT et SFC <strong>en hausse</strong>.</li>\n<li>APU : on peut le faire <strong>fonctionner plus haut</strong> qu'on ne peut le <strong>démarrer</strong>.</li></ul>"}], "oral": ["Comment évoluent la poussée et la consommation spécifique avec l'altitude à TAS constante ? Et avec la TAS à altitude constante ?", "Qu'est-ce qu'un moteur flat-rated ? Décris l'évolution de la poussée et de la TIT avec l'OAT.", "Définis l'EPR.", "Compare la poussée réduite (FLEX) et la poussée détarée (DERATE) : principe, avantages, limites.", "Quel est l'effet d'un prélèvement d'air sur le régime, l'EGT, la poussée et la consommation ?", "Quelles sont les tâches d'un APU ? Pourquoi son altitude max de démarrage est-elle plus basse que son altitude max d'utilisation ?", "Cite les causes d'arrêt automatique d'un APU."]}};
